48	    uint64_t l0bSize = 0;
49	    uint64_t l0cSize = 0;
50	};
51	
52	class TilingBase {
53	public:
54	    explicit TilingBase(gert::TilingContext* context) : context_(context)
55	    {}
56	
57	    virtual ~TilingBase() = default;
58	
59	    // Tiling执行框架
60	    //     1、GRAPH_SUCCESS: 成功，并且不需要继续执行后续Tiling类的实现
61	    //     2、GRAPH_FAILED: 失败，中止整个Tiling流程
62	    //     3、GRAPH_PARAM_INVALID: 本类不支持，需要继续往下执行其他Tiling类的实现
63	    ge::graphStatus DoTiling()
64	    {
65	        auto ret = GetShapeAttrsInfo();
66	        if (ret != ge::GRAPH_SUCCESS) {
67	            return ret;
68	        }
69	        ret = GetPlatformInfo();
70	        if (ret != ge::GRAPH_SUCCESS) {
71	            return ret;
72	        }
73	        if (!IsCapable()) {
74	            return ge::GRAPH_PARAM_INVALID;
75	        }
76	        ret = DoOpTiling();
77	        if (ret != ge::GRAPH_SUCCESS) {
78	            return ret;
79	        }
80	        ret = GetWorkspaceSize();
81	        if (ret != ge::GRAPH_SUCCESS) {
82	            return ret;
83	        }
84	        context_->SetTilingKey(GetTilingKey());
85	        DumpTilingInfo();
86	        return ge::GRAPH_SUCCESS;
87	    }
88	
89	    // 更新 context
90	    virtual void Reset(gert::TilingContext *context)
91	    {
92	        context_ = context;
93	    }
94	
95	  protected:
96	    virtual bool IsCapable() = 0;
97	    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
98	    virtual ge::graphStatus GetPlatformInfo() = 0;
99	    // 2、获取INPUT/OUTPUT/ATTR信息
100	    virtual ge::graphStatus GetShapeAttrsInfo() = 0;
101	    // 3、计算数据切分TilingData
102	    virtual ge::graphStatus DoOpTiling() = 0;
103	    // 4、计算TilingKey
104	    [[nodiscard]] virtual uint64_t GetTilingKey() const = 0;
105	    // 5、计算Workspace 大小
106	    virtual ge::graphStatus GetWorkspaceSize() = 0;
107	    // 6、Dump Tiling数据
108	    virtual void DumpTilingInfo()
109	    {
110	        int32_t enable = 1;
111	        if (enable != 1) {
112	            return;
113	        }
114	        auto buf = (uint32_t *)context_->GetRawTilingData()->GetData();
115	        auto bufLen = context_->GetRawTilingData()->GetDataSize();
116	        std::ostringstream oss;
117	        oss << "Start to dump tiling info. tilingkey:" << context_->GetTilingKey() << ", tiling data size:" << bufLen
118	            << ", content:";
119	        for (size_t i = 0; i < bufLen / sizeof(uint32_t); i++) {
120	            oss << *(buf + i) << ",";
121	            if (oss.str().length() > 640) { // Split according to 640 to avoid truncation
122	                OP_LOGD(context_, "%s", oss.str().c_str());
123	                oss.str("");
124	            }
125	        }
126	        OP_LOGD(context_, "%s", oss.str().c_str());
127	    }
128	
129	    static uint32_t CalcTschBlockDim(uint32_t sliceNum, uint32_t aicCoreNum, uint32_t aivCoreNum)
130	    {
131	        uint32_t ration;
132	        if (aicCoreNum == 0 || aivCoreNum == 0 || aicCoreNum > aivCoreNum) {
133	            return sliceNum;
134	        }
135	        ration = aivCoreNum / aicCoreNum;
136	        return (sliceNum + (ration - 1)) / ration;
137	    }
138	
139	    template <typename T> [[nodiscard]] std::string GetShapeDebugStr(const T &shape) const
140	    {
141	        std::ostringstream oss;
142	        oss << "[";
143	        const int32_t dimNum = static_cast<int>(shape.GetDimNum());
144	        if (dimNum > 0) {
145	            for (int32_t i = 0; i < dimNum - 1; ++i) {
146	                oss << shape.GetDim(i) << ", ";
147	            }
148	            oss << shape.GetDim(dimNum - 1);
149	        }
150	        oss << "]";
151	        return oss.str();
152	    }
153	
154	    [[nodiscard]] std::string GetTensorDebugStr(const gert::StorageShape *shape,
155	                                                const gert::CompileTimeTensorDesc *tensor)
156	    {
157	        if (shape == nullptr || tensor == nullptr) {
158	            return "nil ";
159	        }
160	        std::ostringstream oss;
161	        oss << "(dtype: " << ge::TypeUtils::DataTypeToSerialString(tensor->GetDataType()) << "),";
162	        oss << "(shape:" << GetShapeDebugStr(shape->GetStorageShape()) << "),";
163	        oss << "(ori_shape:" << GetShapeDebugStr(shape->GetOriginShape()) << "),";
164	        oss << "(format: "
165	            << ge::TypeUtils::FormatToSerialString(
166	                   static_cast<ge::Format>(ge::GetPrimaryFormat(tensor->GetStorageFormat())))
167	            << "),";
168	        oss << "(ori_format: " << ge::TypeUtils::FormatToSerialString(tensor->GetOriginFormat()) << ") ";
169	        return oss.str();
170	    }
171	
172	    [[nodiscard]] std::string GetTilingContextDebugStr()
173	    {
174	        std::ostringstream oss;
175	        for (size_t i = 0; i < context_->GetComputeNodeInfo()->GetInputsNum(); ++i) {
176	            oss << "input" << i << ": ";
177	            oss << GetTensorDebugStr(context_->GetInputShape(i), context_->GetInputDesc(i));
178	        }
179	
180	        for (size_t i = 0; i < context_->GetComputeNodeInfo()->GetOutputsNum(); ++i) {
181	            oss << "output" << i << ": ";
182	            oss << GetTensorDebugStr(context_->GetOutputShape(i), context_->GetOutputDesc(i));
183	        }
184	        return oss.str();
185	    }
186	
187	    [[nodiscard]] std::string GetTilingDataDebugStr() const
188	    {
189	        auto rawTilingData = context_->GetRawTilingData();
190	        auto rawTilingDataSize = rawTilingData->GetDataSize();
191	        auto data = reinterpret_cast<const int32_t *>(rawTilingData->GetData());
192	        size_t len = rawTilingDataSize / sizeof(int32_t);
193	        std::ostringstream oss;
194	        for (size_t i = 0; i < len; i++) {
195	            oss << data[i] << ", ";
196	        }
197	        return oss.str();
198	    }
199	
200	  protected:
201	    gert::TilingContext *context_ = nullptr;
202	    std::unique_ptr<platform_ascendc::PlatformAscendC> ascendcPlatform_{nullptr};
203	    uint32_t blockDim_{0};
204	    uint64_t workspaceSize_{0};
205	    uint64_t tilingKey_{0};
206	    AiCoreParams aicoreParams_;
207	};
