    ge::graphStatus CheckContext();
    bool AnalyzeAttrs();
    bool CrossShapeVerify(const gert::Shape &queryRopeShape, const gert::Shape &keyRopeShap);
    bool AnalyzeDimLayout(const gert::Shape &queryShape,
                          const gert::Shape &keyShape,
                          const gert::Shape &queryIndexShape,
                          const gert::Shape &topKShape,
                          size_t layoutLen,
                          const gert::Shape &queryRopeShape,
                          const gert::Shape &keyRopeShape);
    bool AnalyzeDtype();
    bool AnalyzeLayout();
    int64_t GetS2RealSize(int32_t sparseMode, int32_t s1Size, int32_t s2Size, int32_t s1Idx);
    bool InitSparseValidArray(std::vector<int64_t> &sparseValidArray);
    inline bool InitLoadValue(const std::vector<int64_t> &sparseValidArray,
                              int64_t validAicNum,
                              int64_t totalSize,
                              const std::vector<int64_t> &sparseStartIdx,
                              std::vector<int64_t> &localValue);
    bool BalanceLoad(const std::vector<int64_t> &sparseValidArray,
                     std::vector<int64_t> &localValue,
                     std::vector<int64_t> &sparseStartIdx);
    bool Balance4DLoad(std::vector<int64_t> &tmpSparseValue,
                       const std::vector<int64_t> sparseValidArray,
                       const int64_t balanceNum);
    bool SetSparseStartIdx(const std::vector<int64_t> &sparseValidArray, int64_t maxCoreNum);
    void SetSparseParamsRegbase(int64_t maxCoreNum);
    int64_t CalcTotalSize();
    void SetMultiCoreParamsRegbase(int64_t totalSize, int64_t coreNum);
    void InitOutputSplit();

    // 基础输入参数
    int32_t bSize = 0;
    int32_t n2Size = 0;
    int32_t gSizeQuery = 0;
    int32_t gSizeQueryIndex = 0;
    int32_t s1Size = 0;
    int32_t s2Size = 0;
    int32_t dSizeQuery = 0;
    int32_t dSizeQueryIndex = 0;
    int32_t kSize = 0;
    int32_t sparseMode = 0;
    int32_t rsvd = 0;
    float scaleValue = 0.0F;
    int64_t sparseBlockSize = 0;

    const char *templateName = "slikbase";

    LayoutType tilingKeyLayout = LayoutType::LAYOUT_BSND;
    TopKRange topKRange = TopKRange::RANGE_0_2K;
    uint32_t aivNum = 0;
    uint32_t aicNum = 0;
    uint64_t l2CacheSize = 0;

    int64_t realT1Size = 0;
    int64_t dQueryRopeSize = 0;
    int64_t dKeyRopeSize = 0;
    int64_t accumS1 = 0;
    int64_t accumS2 = 0;
    int64_t maxS1Val = 0;
    int64_t maxS2Val = 0;

    platform_ascendc::SocVersion socVersion = platform_ascendc::SocVersion::ASCEND910B;
    bool deterministic = false;
    bool hasRope = false;

    const char *opName = nullptr;
    const char *inputLayout = nullptr;

    std::vector<int64_t> actualSeqLenData;
    std::vector<int64_t> actualSeqLenKData;

    SparseLightningIndexerGradKLLossEnhanceTilingData *tilingData =
        context_->GetTilingData<SparseLightningIndexerGradKLLossEnhanceTilingData>();
    SLIGradKLLossBaseParams *sliGradkllossBaseParams_ = &tilingData->baseParams;
    SLIGradKLLossMultiCoreParams *sliGradkllossMultiCoreParams_ = &tilingData->multiCoreParams;
};

