56	template <typename T> static auto AlignUp(T num1, T num2) -> T
57	{
58	    if (num2 == 0) {
59	        return 0;
60	    }
61	    if (num1 < 0) {
62	        return -(-num1 / num2) * num2;
63	    }
64	    return (num1 + num2 - 1) / num2 * num2;
65	}
66	
67	template <typename T> static auto AlignDown(T num1, T num2) -> T
68	{
69	    if (num2 == 0) {
70	        return 0;
71	    }
72	    return num1 / num2 * num2;
73	}
74	
75	template <typename T> static auto CeilDivision(T num1, T num2) -> T
76	{
77	    if (num2 == 0) {
78	        return 0;
79	    }
80	    return (num1 + num2 - 1) / num2;
81	}
82	
83	template <typename T> static auto CeilDiv(const T n1, const T n2) -> T
84	{
85	    if (n1 == 0) {
86	        return 0;
87	    }
88	    return (n2 != 0) ? (((n1 - 1) / n2) + 1) : n1;
89	}
90	
91	template <typename T> static auto CalcTailSize(T num1, T num2) -> T
92	{
93	    if (num2 == 0) {
94	        return 0;
95	    }
96	    T mod = num1 % num2;
97	    return mod != 0 ? mod : num2;
98	}
