179	void SparseLightningIndexerGradKLLossEnhanceTilingBase::GetActualSeqLenData(int64_t inputIdx,
180	                                                                            std::vector<int64_t> &res,
181	                                                                            int64_t &actualLen) const
182	{
183	    auto actualSeqLenTensor = context_->GetOptionalInputTensor(inputIdx);
184	    if (actualSeqLenTensor == nullptr) {
185	        OP_LOGW(context_, "[%s]actualSeqLenTensor is null pointer", templateName);
186	        return;
187	    }
188	    auto &actualSeqLenShape = actualSeqLenTensor->GetShape().GetStorageShape();
189	    if (actualSeqLenShape.GetDimNum() != 1) {
190	        OP_LOGW(context_,
191	                "[%s]actualSeqLenShape is invalid %lu %ld",
192	                templateName,
193	                actualSeqLenShape.GetDimNum(),
194	                actualSeqLenShape.GetDim(0));
195	        return;
196	    }
197	    /* Get Data from tensor. */
198	    const int64_t *value = actualSeqLenTensor->GetData<int64_t>();
199	    if (value == nullptr) {
200	        OP_LOGW(context_, "[%s]actualSeqLenTensor data is null pointer", templateName);
201	        return;
202	    }
203	    int64_t seqLen = actualSeqLenShape.GetDim(0);
204	    try {
205	        res.reserve(seqLen);
206	    } catch (...) {
207	        OPS_REPORT_VECTOR_INNER_ERR(opName, "Init actual_seq_len failed, array is too long.");
208	        return;
209	    }
210	    res.emplace_back(value[0]);
211	    actualLen++;
212	    for (int64_t i = 1; i < seqLen; ++i) {
213	        auto qLen = value[i] - value[i - 1]; // value[i]代表偏移位置的索引
214	        qLen = qLen < 0 ? 0 : qLen;
215	        res.emplace_back(qLen);
216	        actualLen++;
217	    }
218	}
