220	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::AnalyzeDimLayout(const gert::Shape &queryShape,
221	                                                                         const gert::Shape &keyShape,
222	                                                                         const gert::Shape &queryIndexShape,
223	                                                                         const gert::Shape &topKShape,
224	                                                                         size_t layoutLen,
225	                                                                         const gert::Shape &queryRopeShape,
226	                                                                         const gert::Shape &keyRopeShape)
227	{
228	    // dRopeSize的确定，有queryRopeShape 和 keyRopeShape
229	    if (layoutLen == 3UL) {
230	        if (inputLayout[0] == 'T' && inputLayout[1] == 'N' && inputLayout[2] == 'D') {
231	            int64_t actualSeqQLen = 0;
232	            int64_t actualSeqKLen = 0;
233	            int64_t t1Size = queryShape.GetDim(0); // TND只有三个数值 T:0 N:1 D:2
234	            int64_t t2Size = keyShape.GetDim(0);
235	            realT1Size = t1Size;
236	            std::fill(actualSeqLenData.begin(), actualSeqLenData.end(), 0);
237	            std::fill(actualSeqLenKData.begin(), actualSeqLenKData.end(), 0);
238	            GetActualSeqLenData(ACTUAL_SEQ_LENGTHS_QUERY_INPUT_INDEX, actualSeqLenData, actualSeqQLen);
239	            GetActualSeqLenData(ACTUAL_SEQ_LENGTHS_KEY_INPUT_INDEX, actualSeqLenKData, actualSeqKLen);
240	            OP_CHECK_IF(actualSeqQLen != actualSeqKLen,
241	                        OP_LOGE(opName, "VarLen scene, q[%ld] is not equal k[%ld].", actualSeqQLen, actualSeqKLen),
242	                        return false);
243	
244	            for (int i = 0; i < actualSeqQLen; i++) {
245	                OP_CHECK_IF(
246	                    actualSeqLenData[i] > actualSeqLenKData[i],
247	                    OP_LOGE(opName,
248	                            "Every element of actualSeqLenData must be less than every element of actualSeqLenKData,\
249	                        but actualSeqLenData[%d]:[%d] is larger than actualSeqLenKData[%d]:[%d].",
250	                            i,
251	                            actualSeqLenData[i],
252	                            i,
253	                            actualSeqLenKData[i]),
254	                    return false);
255	            }
256	            bSize = actualSeqQLen;
257	            accumS1 = std::accumulate(actualSeqLenData.begin(), actualSeqLenData.begin() + actualSeqQLen, 0LL);
258	            accumS2 = std::accumulate(actualSeqLenKData.begin(), actualSeqLenKData.begin() + actualSeqKLen, 0LL);
259	            OP_CHECK_IF(t1Size != accumS1 || t2Size != accumS2,
260	                        OP_LOGE(opName,
261	                                "Query Tsize(%ld) and key Tsize(%ld) must be equal to sum of seqQLen(%ld) and "
262	                                "seqkLen(%ld), respectively.",
263	                                t1Size,
264	                                t2Size,
265	                                accumS1,
266	                                accumS2),
267	                        return false);
268	            OP_CHECK_IF(s1Size > s2Size || t1Size > t2Size || accumS1 > accumS2,
269	                        OP_LOGE(opName,
270	                                "Query s1Size(%ld), t1Size(%ld) and the sum of seqQLen(%ld) must be small than Key "
271	                                "s2Size(%ld), t2Size(%ld) and seqkLen(%ld), respectively.",
272	                                s1Size,
273	                                t1Size,
274	                                accumS1,
275	                                s2Size,
276	                                t2Size,
277	                                accumS2),
278	                        return false);
279	            maxS1Val = *std::max_element(actualSeqLenData.begin(), actualSeqLenData.end());
280	            maxS2Val = *std::max_element(actualSeqLenKData.begin(), actualSeqLenKData.end());
281	            s1Size = maxS1Val;
282	            s2Size = maxS2Val;
283	            n2Size = keyShape.GetDim(1);
284	            OP_CHECK_IF(
285	                (n2Size == 0),
286	                OPS_REPORT_VECTOR_INNER_ERR(opName, "N2 is zero."),
287	                return false
288	            );
289	            gSizeQuery = queryShape.GetDim(1) / n2Size;
290	            gSizeQueryIndex = queryIndexShape.GetDim(1) / n2Size;
291	            dSizeQuery = queryShape.GetDim(2);
292	            dSizeQueryIndex = queryIndexShape.GetDim(2);
293	            kSize = topKShape.GetDim(2);
294	            OP_CHECK_IF(kSize > BUFFER_SIZE_BYTE_8K || kSize % BUFFER_SIZE_BYTE_1K > 0,
295	                        OP_LOGE(opName,
296	                                "topK(%d) should be small than 8192, and should be an integer multiple of 1024.",
297	                                kSize),
298	                        return false);
299	            topKRange = (kSize <= BUFFER_SIZE_BYTE_2K) ? TopKRange::RANGE_0_2K : TopKRange::RANGE_2K_8K;
300	            if (hasRope) {
301	                dQueryRopeSize = queryRopeShape.GetDim(2);
302	                dKeyRopeSize = keyRopeShape.GetDim(2);
303	            }
304	            tilingData->baseParams.set_layoutType(LAYOUT_TND);
305	            tilingKeyLayout = LayoutType::LAYOUT_TND;
306	        }
307	    } else if (layoutLen == 4UL) {
308	        if (inputLayout[0] == 'B' && inputLayout[1] == 'S' && inputLayout[2] == 'N' && inputLayout[3] == 'D') {
309	            bSize = queryShape.GetDim(0);
310	            s1Size = queryShape.GetDim(1);
311	            s2Size = keyShape.GetDim(1);
312	            n2Size = keyShape.GetDim(2);
313	            OP_CHECK_IF(
314	                s1Size > s2Size,
315	                OP_LOGE(
316	                    opName,
317	                    "Query s1Size(%ld) must be small than Key s2Size(%ld).",
318	                    s1Size, s2Size),
319	                return false);
320	            OP_CHECK_IF(
321	                (n2Size == 0),
322	                OPS_REPORT_VECTOR_INNER_ERR(opName, "N2 is zero."),
323	                return false
324	            );
325	            gSizeQuery = queryShape.GetDim(2) / n2Size;
326	            gSizeQueryIndex = queryIndexShape.GetDim(2) / n2Size;
327	            dSizeQuery = queryShape.GetDim(3);
328	            dSizeQueryIndex = queryIndexShape.GetDim(3);
329	            kSize = topKShape.GetDim(3);
330	            OP_CHECK_IF(kSize > BUFFER_SIZE_BYTE_8K || kSize % BUFFER_SIZE_BYTE_1K > 0,
331	                        OP_LOGE(opName,
332	                                "topK(%d) should be small than 8192, and should be an integer multiple of 1024.",
333	                                kSize),
334	                        return false);
335	            topKRange = (kSize <= BUFFER_SIZE_BYTE_2K) ? TopKRange::RANGE_0_2K : TopKRange::RANGE_2K_8K;
336	            if (hasRope) {
337	                dQueryRopeSize = queryRopeShape.GetDim(3);
338	                dKeyRopeSize = keyRopeShape.GetDim(3);
339	            }
340	            tilingData->baseParams.set_layoutType(LAYOUT_BSND);
341	            tilingKeyLayout = LayoutType::LAYOUT_BSND;
342	        }
343	    } else {
344	        return false;
345	    }
346	
347	    return true;
348	}
