350	// 对每一个输入参数的变量类型进行对比校验
351	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::AnalyzeDtype()
352	{
353	    // 对8个必须输入的参数进行参数类型判断
354	    // 输入空指针校验
355	    auto queryDesc = context_->GetInputDesc(QUERY_INPUT_INDEX);
356	    auto keyDesc = context_->GetInputDesc(KEY_INPUT_INDEX);
357	    auto queryIndexDesc = context_->GetInputDesc(QUERY_INDEX_INPUT_INDEX);
358	    auto keyIndexDesc = context_->GetInputDesc(KEY_INDEX_INPUT_INDEX);
359	    auto weightsDesc = context_->GetInputDesc(WEIGHT_INPUT_INDEX);
360	    auto sparseIndicesDesc = context_->GetInputDesc(SPARSE_INDICES_INPUT_INDEX);
361	    auto softmaxMaxDesc = context_->GetInputDesc(SOFTMAX_MAX_INPUT_INDEX);
362	    auto softmaxSumDesc = context_->GetInputDesc(SOFTMAX_SUM_INPUT_INDEX);
363	    OP_CHECK_NULL_WITH_CONTEXT(context_, queryDesc);
364	    OP_CHECK_NULL_WITH_CONTEXT(context_, keyDesc);
365	    OP_CHECK_NULL_WITH_CONTEXT(context_, queryIndexDesc);
366	    OP_CHECK_NULL_WITH_CONTEXT(context_, keyIndexDesc);
367	    OP_CHECK_NULL_WITH_CONTEXT(context_, weightsDesc);
368	    OP_CHECK_NULL_WITH_CONTEXT(context_, sparseIndicesDesc);
369	    OP_CHECK_NULL_WITH_CONTEXT(context_, softmaxMaxDesc);
370	    OP_CHECK_NULL_WITH_CONTEXT(context_, softmaxSumDesc);
371	
372	    // 以下5个为16类型保持一致
373	    auto queryDtype = queryDesc->GetDataType();
374	    auto keyDtype = keyDesc->GetDataType();
375	    auto queryIndexDtype = queryIndexDesc->GetDataType();
376	    auto keyIndexDtype = keyIndexDesc->GetDataType();
377	    auto weightsDtype = weightsDesc->GetDataType();
378	
379	    // 以下3个为32类型
380	    auto sparseIndicesDtype = sparseIndicesDesc->GetDataType();
381	    auto softmaxMaxDtype = softmaxMaxDesc->GetDataType();
382	    auto softmaxSumDtype = softmaxSumDesc->GetDataType();
383	
384	    bool same16 = false; // 判断输入为fp16或者部分16的是否一致
385	    bool same32 = false; // 判断输入为int32或者fp32的类型是否正确
386	    if (queryDtype == ge::DT_FLOAT16 && keyDtype == ge::DT_FLOAT16 && queryIndexDtype == ge::DT_FLOAT16 &&
387	        keyIndexDtype == ge::DT_FLOAT16 && weightsDtype == ge::DT_FLOAT16) {
388	        same16 = true;
389	    } else if (queryDtype == ge::DT_BF16 && keyDtype == ge::DT_BF16 && queryIndexDtype == ge::DT_BF16 &&
390	               keyIndexDtype == ge::DT_BF16 && weightsDtype == ge::DT_BF16) {
391	        same16 = true;
392	    } else {
393	        OP_LOGW(context_,
394	                "InputDtype is not same.: queryDtype[%s], keyDtype[%s], queryIndexDtype[%s], keyIndexDtype[%s], "
395	                "weightsDtype[%s]",
396	                ge::TypeUtils::DataTypeToSerialString(queryDtype).c_str(),
397	                ge::TypeUtils::DataTypeToSerialString(keyDtype).c_str(),
398	                ge::TypeUtils::DataTypeToSerialString(queryIndexDtype).c_str(),
399	                ge::TypeUtils::DataTypeToSerialString(keyIndexDtype).c_str(),
400	                ge::TypeUtils::DataTypeToSerialString(weightsDtype).c_str());
401	        same16 = false;
402	    }
403	    if (sparseIndicesDtype == ge::DT_INT32 && softmaxMaxDtype == ge::DT_FLOAT && softmaxSumDtype == ge::DT_FLOAT) {
404	        same32 = true;
405	    } else {
406	        OP_LOGW(context_,
407	                "InputDtype is fault: sparseIndicesDtype must be int32, but[%s]; softmaxMaxDtype must be float32, "
408	                "but[%s]; softmaxSumDtype must be float32, but[%s].",
409	                ge::TypeUtils::DataTypeToSerialString(sparseIndicesDtype).c_str(),
410	                ge::TypeUtils::DataTypeToSerialString(softmaxMaxDtype).c_str(),
411	                ge::TypeUtils::DataTypeToSerialString(softmaxSumDtype).c_str());
412	        same32 = false;
413	    }
414	    // 所有类型不满足返回false
415	    if (same16 == false || same32 == false) {
416	        return false;
417	    }
418	    OP_LOGW(context_,
419	            "InputDtype: queryDtype[%s], keyDtype[%s], queryIndexDtype[%s], keyIndexDtype[%s], weightsDtype[%s],",
420	            ge::TypeUtils::DataTypeToSerialString(queryDtype).c_str(),
421	            ge::TypeUtils::DataTypeToSerialString(keyDtype).c_str(),
422	            ge::TypeUtils::DataTypeToSerialString(queryIndexDtype).c_str(),
423	            ge::TypeUtils::DataTypeToSerialString(keyIndexDtype).c_str(),
424	            ge::TypeUtils::DataTypeToSerialString(weightsDtype).c_str());
425	    OP_LOGW(context_,
426	            "sparseIndicesDtype[%s], softmaxMaxDtype[%s], softmaxSumDtype[%s].",
427	            ge::TypeUtils::DataTypeToSerialString(sparseIndicesDtype).c_str(),
428	            ge::TypeUtils::DataTypeToSerialString(softmaxMaxDtype).c_str(),
429	            ge::TypeUtils::DataTypeToSerialString(softmaxSumDtype).c_str());
430	    return true;
431	}
