434	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::CrossShapeVerify(const gert::Shape &queryRopeShape,
435	                                                                         const gert::Shape &keyRopeShape)
436	{
437	    auto queryShape = context_->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
