441	    auto weightsShape = context_->GetInputShape(WEIGHT_INPUT_INDEX)->GetStorageShape();
442	    auto sparseIndicesShape = context_->GetInputShape(SPARSE_INDICES_INPUT_INDEX)->GetStorageShape();
443	    auto softmaxMaxShape = context_->GetInputShape(SOFTMAX_MAX_INPUT_INDEX)->GetStorageShape();
444	    auto softmaxSumShape = context_->GetInputShape(SOFTMAX_SUM_INPUT_INDEX)->GetStorageShape();
445	    // 下面数字对应shape输入位置
446	    if (inputLayout[0] == 'T' && inputLayout[1] == 'N' && inputLayout[2] == 'D') {
447	        int64_t t1Len = queryShape[0];
448	        int64_t n1Len = queryShape[1];
449	        int64_t n1indexLen = queryIndexShape[1];
450	        int64_t t2Len = keyShape[0];
451	        int64_t n2Len = keyShape[1];
452	        // 验证T1
453	        OP_CHECK_IF(
454	            queryIndexShape[0] != t1Len || weightsShape[0] != t1Len || softmaxMaxShape[1] != t1Len ||
455	                softmaxSumShape[1] != t1Len,
456	            OPS_REPORT_VECTOR_INNER_ERR(
457	                opName,
458	                "CrossShapeVerify T1 is failed, the value of query[0], query_index[0], weights[0], softmax_max[1] \
459	                 and softmax_sum[1] are respectively (%ld), (%ld), (%ld), (%ld), (%ld). Their values should be equal.",
460	                queryShape[0],
461	                queryIndexShape[0],
462	                weightsShape[0],
463	                softmaxMaxShape[1],
464	                softmaxSumShape[1]),
465	            return false);
466	        // 验证N Index
467	        OP_CHECK_IF(
468	            queryIndexShape[1] != weightsShape[1],
469	            OPS_REPORT_VECTOR_INNER_ERR(opName,
470	                                        "CrossShapeVerify N index is failed, the value of query_index[1] and "
