695	        // 验证N2
696	        OP_CHECK_IF(keyIndexShape[2] != n2Len || softmaxMaxShape[1] != n2Len || softmaxSumShape[1] != n2Len,
697	                    OPS_REPORT_VECTOR_INNER_ERR(
698	                        opName,
