737	                                        "CrossShapeVerify query-key shape D is failed, the value of query[3] and "
738	                                        "key[3] are respectively (%ld), (%ld). Their values should be equal.",
739	                                        queryShape[3],
740	                                        keyShape[3]),
741	            return false);
742	        OP_CHECK_IF(queryIndexShape[3] != keyIndexShape[3],
743	                    OPS_REPORT_VECTOR_INNER_ERR(
744	                        opName,
745	                        "CrossShapeVerify query-key_index shape D is Failed, the value of query_index[3] and "
746	                        "key_index[3] are respectively (%ld), (%ld). Their values should be equal.",
747	                        queryIndexShape[3],
748	                        keyIndexShape[3]),
749	                    return false);
750	        // 验证ROPE是否使能
751	        OP_CHECK_IF(
752	            !hasRope,
753	            OPS_REPORT_VECTOR_INNER_ERR(opName, "CrossShapeVerify query or key rope is failed, rope can't be null"),
754	            return false);
755	        if (hasRope) {
756	            // 验证queryrope
757	            OP_CHECK_IF(
758	                queryRopeShape[0] != bLen || queryRopeShape[1] != s1Len || queryRopeShape[2] != n1Len,
759	                OPS_REPORT_VECTOR_INNER_ERR(
760	                    opName,
761	                    "CrossShapeVerify query_rope is failed, the value of query_rope[0] is (%ld), "
762	                    "it should be equal to bSize(%ld). the value of query_rope[1] is (%ld), "
763	                    "it should be equal to s1Size(%ld), the value of query_rope[2] is (%ld), "
764	                    "it should be equal to nQuerySize(%ld).",
765	                    queryRopeShape[0],
766	                    bLen,
767	                    queryRopeShape[1],
768	                    s1Len,
769	                    queryRopeShape[2],
770	                    n1Len),
771	                return false);
772	            // 验证keyrope
773	            OP_CHECK_IF(
774	                keyRopeShape[0] != bLen || keyRopeShape[1] != s2Len || keyRopeShape[2] != n2Len,
775	                OPS_REPORT_VECTOR_INNER_ERR(
776	                    opName,
777	                    "CrossShapeVerify key_rope is failed, the value of key_rope[0] is (%ld), "
778	                    "it should be equal to bSize(%ld), the value of key_rope[1] is (%ld), "
779	                    "it should be equal to s2Size(%ld). the value of key_rope[2] is (%ld), "
780	                    "it should be equal to n2Size(%ld)",
781	                    keyRopeShape[0],
782	                    bLen,
783	                    keyRopeShape[1],
784	                    s2Len,
785	                    keyRopeShape[2],
786	                    n2Len),
787	                return false);
788	            // 验证rope D 数字是否正确
789	            OP_CHECK_IF(queryRopeShape[3] != DROPE_SIZE_64,
790	                        OPS_REPORT_VECTOR_INNER_ERR(opName,
791	                                                    "CrossShapeVerify failed, shape D of query_rope  must be 64, but "
792	                                                    "the value of query_rope[3] is (%ld).",
793	                                                    queryRopeShape[3]),
794	                        return false);
795	            OP_CHECK_IF(
796	                keyRopeShape[3] != DROPE_SIZE_64,
797	                OPS_REPORT_VECTOR_INNER_ERR(
798	                    opName,
799	                    "CrossShapeVerify failed, shape D of key_rope must be 64, but the value of key_rope[3] is (%ld).",
800	                    keyRopeShape[3]),
801	                return false);
802	            // 验证rope D
803	            OP_CHECK_IF(queryRopeShape[3] != keyRopeShape[3],
804	                        OPS_REPORT_VECTOR_INNER_ERR(opName,
805	                                                    "CrossShapeVerify query_rope D is not equal to key_rope D, the "
806	                                                    "value of queryRope[3] and keyRope[3] is (%ld), (%ld).",
807	                                                    queryRopeShape[3],
808	                                                    keyRopeShape[3]),
809	                        return false);
810	        }
811	    } else {
812	        return false;
813	    }
814	    return true;
815	}
