817	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::AnalyzeLayout()
818	{
819	    auto &queryShape = context_->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
820	    auto &keyShape = context_->GetInputShape(KEY_INPUT_INDEX)->GetStorageShape();
821	    auto &queryIndexShape = context_->GetInputShape(QUERY_INDEX_INPUT_INDEX)->GetStorageShape();
822	    auto &keyIndexShape = context_->GetInputShape(KEY_INDEX_INPUT_INDEX)->GetStorageShape();
823	    auto &topKShape = context_->GetInputShape(SPARSE_INDICES_INPUT_INDEX)->GetStorageShape();
824	
825	    auto queryRope = context_->GetOptionalInputShape(QUERY_ROPE_INPUT_INDEX);
826	    bool hasQueryRope = queryRope != nullptr && queryRope->GetStorageShape().GetDimNum() != 0;
827	    auto keyRope = context_->GetOptionalInputShape(KEY_ROPE_INPUT_INDEX);
828	    bool hasKeyRope = keyRope != nullptr && keyRope->GetStorageShape().GetDimNum() != 0;
829	    if (hasQueryRope != hasKeyRope) {
830	        OP_LOGE(opName, "query_rope and key_rope should be present or absent at the same time, check this.");
831	        return false;
832	    }
833	    // TND和BSND的dim位置不同来赋值
834	    hasRope = hasQueryRope && hasKeyRope;
835	    auto &queryRopeShape = queryRope->GetStorageShape();
836	    auto &keyRopeShape = keyRope->GetStorageShape();
837	
838	    size_t layoutLen = strlen(inputLayout);
839	    OP_CHECK_IF(
840	        (queryShape.GetDimNum() != layoutLen ||
841	        keyShape.GetDimNum() != layoutLen ||
842	        queryIndexShape.GetDimNum() != layoutLen ||
843	        keyIndexShape.GetDimNum() != layoutLen),
