1005	inline bool SparseLightningIndexerGradKLLossEnhanceTilingBase::InitLoadValue(
1006	    const std::vector<int64_t> &sparseValidArray,
1007	    int64_t validAicNum,
1008	    int64_t totalSize,
1009	    const std::vector<int64_t> &sparseStartIdx,
1010	    std::vector<int64_t> &localValue)
1011	{
1012	    for (int64_t idx = 0; idx < validAicNum; ++idx) {
1013	        int64_t start = sparseStartIdx[idx];
1014	        int64_t end = ((idx + 1) < validAicNum) ? sparseStartIdx[idx + 1] : totalSize;
1015	        if (start < totalSize) {
1016	            localValue[idx] = std::accumulate(sparseValidArray.begin() + start, sparseValidArray.begin() + end, 0LL);
1017	        } else {
1018	            break;
1019	        }
1020	    }
1021	    return true;
1022	}
