1024	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::BalanceLoad(const std::vector<int64_t> &sparseValidArray,
1025	                                                                    std::vector<int64_t> &localValue,
1026	                                                                    std::vector<int64_t> &sparseStartIdx)
1027	{
1028	    // to avoid buffer overflow, or maybe sometimes we want to only verify single core
1029	    int64_t validAicNum =
1030	        std::min(static_cast<int64_t>(sliGradkllossMultiCoreParams_->get_coreNum()), static_cast<int64_t>(aicNum));
1031	    int64_t totalSize = sliGradkllossMultiCoreParams_->get_totalSize();
1032	    int64_t maxVal = *std::max_element(localValue.begin(), localValue.end());
1033	    int64_t tmpMaxVal = maxVal;
1034	
1035	    // 从前往后遍历
1036	    for (int64_t idx = 1; idx < validAicNum; ++idx) {
1037	        int64_t start = sparseStartIdx[idx];
1038	        if (start < totalSize && start > 0 && ((localValue[idx - 1] + sparseValidArray[start]) < maxVal)) {
1039	            localValue[idx - 1] += sparseValidArray[start];
1040	            localValue[idx] -= sparseValidArray[start];
1041	            sparseStartIdx[idx] += 1;
1042	        } else if (start == totalSize) {
1043	            break;
1044	        }
1045	    }
1046	    tmpMaxVal = *std::max_element(localValue.begin(), localValue.end());
1047	
1048	    // 从后往前遍历
1049	    for (int64_t idx = validAicNum - 1; idx > 0; --idx) {
1050	        int64_t start = sparseStartIdx[idx];
1051	        if (start == totalSize) {
1052	            if (sparseStartIdx[idx - 1] == totalSize) {
1053	                continue;
1054	            }
1055	            localValue[idx - 1] -= sparseValidArray[start - 1];
1056	            localValue[idx] = sparseValidArray[start - 1];
1057	            sparseStartIdx[idx] -= 1;
1058	        } else if (start > 0) {
1059	            if ((localValue[idx] + sparseValidArray[start - 1]) >= tmpMaxVal) {
1060	                continue;
1061	            }
1062	            localValue[idx - 1] -= sparseValidArray[start - 1];
1063	            localValue[idx] += sparseValidArray[start - 1];
1064	            sparseStartIdx[idx] -= 1;
1065	        } else {
1066	            break;
1067	        }
1068	    }
1069	    tmpMaxVal = *std::max_element(localValue.begin(), localValue.end());
1070	
1071	    return (tmpMaxVal >= maxVal) ? false : true;
1072	}
1073	
1074	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::Balance4DLoad(std::vector<int64_t> &tmpSparseValue,
1075	                                                                      const std::vector<int64_t> sparseValidArray,
1076	                                                                      const int64_t balanceNum)
1077	{
1078	    int64_t tmpIndex = 0;
1079	    tmpSparseValue[tmpIndex] = 0;
1080	    int64_t sumTmpArray = 0;
1081	    for (int64_t idx = 0; idx < sparseValidArray.size(); ++idx) {
1082	        // 第一次分到最后一块后就没必须计算，剩余的直接分给最后一个核即可
1083	        if (tmpIndex == static_cast<int64_t>(tmpSparseValue.size()) - 1) {
1084	            break;
1085	        }
1086	
1087	        int64_t sumTmpArrayLast = sumTmpArray; // 记录上次的总和值
1088	        sumTmpArray += sparseValidArray[idx];
1089	        if (sumTmpArray == balanceNum) {
1090	            tmpIndex = (tmpIndex + 1 < tmpSparseValue.size()) ? tmpIndex + 1 : tmpSparseValue.size() - 1;
1091	            tmpSparseValue[tmpIndex] = idx + 1; // 刚好等于均值时核的末尾为idx
1092	            sumTmpArray = 0; // 重新计算总和
1093	        } else if (sumTmpArray > balanceNum) {
1094	            tmpIndex = (tmpIndex + 1 < tmpSparseValue.size()) ? tmpIndex + 1 : tmpSparseValue.size() - 1;
1095	            // 第一次总和大于均值，判断前面一次和当前哪个更接近均值
1096	            if (balanceNum - sumTmpArrayLast >= sumTmpArray - balanceNum) {
1097	                // 当前更接近，取当前值
1098	                tmpSparseValue[tmpIndex] = idx + 1; // 刚好等于均值时核的末尾为idx
1099	            } else {
1100	                // 上一次更接近， 取上一次值
1101	                tmpSparseValue[tmpIndex] = idx; // 刚好等于均值时核的末尾为idx                
1102	                idx--; // 记录的上一个值，重新计算时也需要从上一个值开始计算                 
1103	            }
1104	            sumTmpArray = 0; // 重新计算总和
1105	        }
1106	    }
1107	    return true;
1108	}
