1110	// 负载均衡
1111	bool SparseLightningIndexerGradKLLossEnhanceTilingBase::SetSparseStartIdx(const std::vector<int64_t> &sparseValidArray,
1112	                                                                          int64_t maxCoreNum)
1113	{
1114	    // to avoid buffer overflow, or maybe sometimes we want to only verify single core
1115	    int64_t validAicNum = static_cast<int64_t>(sliGradkllossMultiCoreParams_->get_coreNum());
1116	    int64_t totalSize = sliGradkllossMultiCoreParams_->get_totalSize();
1117	    int64_t *sparseStartIdx = sliGradkllossMultiCoreParams_->get_bS1Ptr();
1118	    int64_t splitFactorSize = sliGradkllossMultiCoreParams_->get_splitFactorSize();
1119	
1120	    OP_CHECK_IF(
1121	        totalSize <= 0, OPS_REPORT_VECTOR_INNER_ERR(opName, "totalSize should be larger than 0."), return false);
1122	    if (tilingKeyLayout == LayoutType::LAYOUT_TND) {
1123	        // initLoad: 使用均分策略, 保证后续不会比均分差
1124	        std::vector<int64_t> localSparseStartIdx(aicNum, totalSize);
1125	        for (int64_t idx = 0; idx < static_cast<int64_t>(aicNum); ++idx) {
1126	            localSparseStartIdx[idx] = std::min((idx * splitFactorSize), totalSize);
1127	        }
1128	        std::vector<int64_t> localValue(validAicNum, 0);
1129	        // 得到了每个核需要计算的S2数量，在T方向平均分配，但是有于有Sparse的存在，localValue中的数值，每个核之间应该差距很大
1130	        InitLoadValue(sparseValidArray, validAicNum, totalSize, localSparseStartIdx, localValue); 
1131	
1132	        // 负载均衡粗调
1133	        std::vector<int64_t> tmpLocalValue(validAicNum, 0);
1134	        std::vector<int64_t> tmpsparseStartIdx(aicNum, totalSize);
1135	        int64_t sparseArraySum =
1136	            std::accumulate(sparseValidArray.begin(), sparseValidArray.end(), 0LL); // 得到所有T上的S2的总数量
1137	        int64_t avgVal = CeilDivision(sparseArraySum, validAicNum); // 平均每个核需要处理的S2的总数量
1138	
1139	        tmpsparseStartIdx[0] = 0;
1140	        for (int64_t idx = 1; idx < static_cast<int64_t>(aicNum); ++idx) {
1141	            int64_t start = tmpsparseStartIdx[idx - 1];
1142	            int64_t singleLoadValue = 0;
1143	            tmpsparseStartIdx[idx] = start;
1144	            while (singleLoadValue < avgVal && tmpsparseStartIdx[idx] < totalSize) {
1145	                singleLoadValue += sparseValidArray[tmpsparseStartIdx[idx]];
1146	                tmpsparseStartIdx[idx] += 1;
1147	            }
1148	
1149	            if ((start + 1) < tmpsparseStartIdx[idx]) {
1150	                int64_t redoSingleLoadValue = singleLoadValue - sparseValidArray[tmpsparseStartIdx[idx] - 1];
1151	                tmpsparseStartIdx[idx] = ((singleLoadValue - avgVal) > (avgVal - redoSingleLoadValue))
1152	                                             ? (tmpsparseStartIdx[idx] - 1)
1153	                                             : (tmpsparseStartIdx[idx]);
1154	                singleLoadValue = ((singleLoadValue - avgVal) > (avgVal - redoSingleLoadValue)) ? redoSingleLoadValue
1155	                                                                                                : singleLoadValue;
1156	                sparseArraySum -= singleLoadValue;
1157	                avgVal = CeilDivision(sparseArraySum, (validAicNum - idx));
1158	            }
1159	        }
1160	
1161	        InitLoadValue(sparseValidArray, validAicNum, totalSize, tmpsparseStartIdx, tmpLocalValue);
1162	
1163	        // 负载均衡精调
1164	        while (BalanceLoad(sparseValidArray, tmpLocalValue, tmpsparseStartIdx)) {
1165	            // 根据负载均衡是否能得到更好预测结果决定是否结束循环
1166	        }
1167	
1168	        // exchange initLoad and 负载均衡
1169	        if ((*std::max_element(localValue.begin(), localValue.end())) >
1170	            (*std::max_element(tmpLocalValue.begin(), tmpLocalValue.end()))) {
1171	            localSparseStartIdx.swap(tmpsparseStartIdx);
1172	            localValue.swap(tmpLocalValue);
1173	        }
1174	        for (int64_t idx = 0; idx < static_cast<int64_t>(aicNum); ++idx) {
1175	            sparseStartIdx[idx] = localSparseStartIdx[idx];
1176	        }
1177	    } else if (tilingKeyLayout == LayoutType::LAYOUT_BSND) {
1178	        int64_t sparseArraySum =
1179	            std::accumulate(sparseValidArray.begin(), sparseValidArray.end(), 0LL); // 得到所有BS上的S2的总数量
1180	        int64_t balanceNum = CeilDivision(sparseArraySum, validAicNum);
1181	        std::vector<int64_t> tmpSparseValue(validAicNum, 0);
1182	        Balance4DLoad(tmpSparseValue, sparseValidArray, balanceNum);
1183	        for (int64_t idx = 0; idx < static_cast<int64_t>(validAicNum); ++idx) {
1184	            sparseStartIdx[idx] = tmpSparseValue[idx];
1185	        }
1186	    }
1187	
1188	    for (int64_t idx = 1; idx < static_cast<int64_t>(MAX_CORE_NUM); ++idx) {
1189	        if (sparseStartIdx[idx] == 0) {
1190	            sparseStartIdx[idx] = static_cast<int64_t>(sparseValidArray.size()); // 赋值为s1最大值
1191	        }
1192	    }
1193	    return true;
1194	}
