1222	void SparseLightningIndexerGradKLLossEnhanceTilingBase::InitOutputSplit()
1223	{
1224	    SLIGradKLLossInitOutputParams *initoutput = &tilingData->initOutputParams;
1225	    auto &dKeyIndexShape = context_->GetOutputShape(1)->GetStorageShape();
1226	    int64_t totalsize = 0;
1227	    uint32_t singlecoresize = 0;
1228	    if (tilingKeyLayout == LayoutType::LAYOUT_TND) {
1229	        int64_t dsizeDkeyindex = dKeyIndexShape.GetDim(2); // TND场景下D为第二个维度
1230	        int64_t totalT2Size = dKeyIndexShape.GetDim(0); // T为第一个维度
1231	        totalsize = totalT2Size * static_cast<int64_t>(dsizeDkeyindex);
1232	    } else if (tilingKeyLayout == LayoutType::LAYOUT_BSND) {
1233	        int64_t dsizeDkeyindex = dKeyIndexShape.GetDim(3); // BSND场景下D为第三个维度
1234	        int64_t totals2Size = dKeyIndexShape.GetDim(1); // s为第二个维度
1235	        totalsize = static_cast<int64_t>(bSize) * totals2Size * dsizeDkeyindex;
1236	    }
1237	    // 单个核均分元素数量
1238	    singlecoresize = static_cast<uint32_t>(
1239	        CeilDivision(totalsize, static_cast<int64_t>(aivNum))); // 输出k-index总大小TD或者BSD 除以 总的aiv核数 向上取整
1240	    initoutput->set_singleCoreSize(singlecoresize);
1241	    initoutput->set_totalOutputSize(totalsize);
1242	}
