1244	ge::graphStatus SparseLightningIndexerGradKLLossEnhanceTilingBase::DoOpTiling()
1245	{
1246	    OP_LOGD(context_, "try template[%s]", templateName);
1247	    // 无多余操作，分核，目前只实现TND场景分核
1248	    int64_t totalSize = CalcTotalSize();
1249	    SetMultiCoreParamsRegbase(totalSize, static_cast<int64_t>(aicNum));
1250	    context_->SetBlockDim(sliGradkllossMultiCoreParams_->get_coreNum()); // 使用的核数确定
1251	
1252	    std::vector<int64_t> shapeVec = {1, kSize};
1253	    ge::Shape srcShape(shapeVec);
1254	    int64_t softmaxTmpBufferSize = BUFFER_SIZE_BYTE_32K; // 需要32KB
1255	    if (kSize > BUFFER_SIZE_BYTE_2K) {
1256	        softmaxTmpBufferSize = BUFFER_SIZE_BYTE_33K; // kSize >2048 需要33kB
1257	    }
1258	    SoftMaxTilingFunc(srcShape, 4, softmaxTmpBufferSize, tilingData->vectorParams.softmaxYTilingData);
1259	
1260	    SetSparseParamsRegbase(static_cast<int64_t>(aicNum));
1261	    InitOutputSplit(); // output分核
1262	    OP_LOGD(context_, "ending template[%s]", templateName);
1263	    return ge::GRAPH_SUCCESS;
1264	}
