1269	                              static_cast<uint8_t>(topKRange),
1270	                              static_cast<uint8_t>(tilingKeyLayout),
1271	                              static_cast<uint8_t>(tilingKeyLayout),
1272	                              static_cast<uint8_t>(sparseMode),
1273	                              static_cast<uint8_t>(deterministic));
1274	}
1275	
1276	ge::graphStatus SparseLightningIndexerGradKLLossEnhanceTilingBase::GetWorkspaceSize()
1277	{
1278	    size_t *workspaces = context_->GetWorkspaceSizes(1);
1279	    int64_t pSize = kSize * (dSizeQuery + dQueryRopeSize) * 2; // 2代表half大小
1280	    int64_t sySize = kSize * dSizeQueryIndex * 2; // 2使用DB
1281	    int64_t bmm1Size = gSizeQuery * kSize * sizeof(float);
1282	    int64_t bmm2Size = gSizeQueryIndex * kSize * sizeof(float);
1283	    int64_t reluGradSize = gSizeQueryIndex * kSize * sizeof(float);
1284	    int64_t psySyncSize = kSize * 2 * sizeof(float); // 2使用DB
1285	    int64_t bmm3Size = kSize * dSizeQueryIndex * sizeof(float);
1286	    int64_t lossSize = sizeof(float) * 128; // 为了512Byte对齐
1287	    int64_t scatterAddOutSize;
1288	    if (tilingKeyLayout == LayoutType::LAYOUT_TND) {
1289	        scatterAddOutSize = accumS2 * dSizeQueryIndex * sizeof(float); // batch
1290	    } else {
1291	        scatterAddOutSize = bSize * s2Size * dSizeQueryIndex * sizeof(float); // batch
1292	    }
1293	
1294	    int64_t singlecoreTotalSize =
1295	        PING_PONG_VALUE * (pSize + bmm1Size + bmm2Size + reluGradSize + sySize + psySyncSize + bmm3Size);
1296	    int64_t multicoreTotalsize =
1297	        singlecoreTotalSize * static_cast<int64_t>(sliGradkllossMultiCoreParams_->get_coreNum()) + scatterAddOutSize +
1298	        lossSize;
1299	    workspaces[0] = static_cast<size_t>(multicoreTotalsize) + WORK_SPACE_RESERVE_SIZE; // 预留16M空间必须加;
1300	    OP_LOGW(context_, "workspace size:[%ld], multicoreTotalsize:[%ld]", workspaces[0], multicoreTotalsize);
1301	    return ge::GRAPH_SUCCESS;
1302	}
1303	
1304	} // namespace optiling
