static const std::string KEY_ROPE_NAME = "key_rope";

ge::graphStatus TilingSparseLightningIndexerGradKLLossEnhance(gert::TilingContext *context)
{
    SparseLightningIndexerGradKLLossEnhanceTilingBase sligKLLossTiling(context);
    if (sligKLLossTiling.DoTiling() != ge::GRAPH_SUCCESS) {
        return ge::GRAPH_FAILED;
    }
    return ge::GRAPH_SUCCESS;
}

ge::graphStatus TilingPrepareForSparseLightningIndexerGradKLLossEnhance(gert::TilingParseContext *context)
{
    OP_LOGW(context, "Start registering tiling.");
    auto compileInfoPtr = context->GetCompiledInfo<SparseLightningIndexerGradKLLossEnhanceCompileInfo>();
    OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null"), return ge::GRAPH_FAILED);

    return ge::GRAPH_SUCCESS;
}

