#ifndef SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_TILING_H
#define SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_TILING_H

#include <cstdint>
#include "kernel_tiling/kernel_tiling.h"
namespace optiling {
// ------------------算子原型索引常量定义----------------
// Inputs Index
constexpr uint32_t QUERY_INPUT_INDEX = 0;
constexpr uint32_t KEY_INPUT_INDEX = 1;
