133	__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::Init(
134	    __gm__ uint8_t *query,
135	    __gm__ uint8_t *key,
136	    __gm__ uint8_t *queryIndex,
137	    __gm__ uint8_t *keyIndex,
138	    __gm__ uint8_t *weight,
139	    __gm__ uint8_t *sparseIndices,
140	    __gm__ uint8_t *softmaxMax,
141	    __gm__ uint8_t *softmaxSum,
142	    __gm__ uint8_t *queryRope,
143	    __gm__ uint8_t *keyRope,
144	    __gm__ uint8_t *actualSeqLengthsQuery,
145	    __gm__ uint8_t *actualSeqLengthsKey,
146	    __gm__ uint8_t *dQueryIndex,
147	    __gm__ uint8_t *dKeyIndex,
148	    __gm__ uint8_t *dWeight,
149	    __gm__ uint8_t *loss,
150	    __gm__ uint8_t *workspace,
151	    const optiling::SparseLightningIndexerGradKLLossEnhanceTilingData *__restrict tiling,
152	    TPipe *tPipe)
153	{
154	    // init tiling data
155	    pipe = tPipe;
156	    tilingData = tiling;
157	
158	    InitConstInfo();
159	
160	    // init input global buffer
161	    queryGm.SetGlobalBuffer((__gm__ Q_T *)query);
162	    keyGm.SetGlobalBuffer((__gm__ KV_T *)key);
163	    queryIndexGm.SetGlobalBuffer((__gm__ Q_T *)queryIndex);
164	    keyIndexGm.SetGlobalBuffer((__gm__ KV_T *)keyIndex);
165	    weightGm.SetGlobalBuffer((__gm__ Q_T *)weight);
166	    topKIndexGm.SetGlobalBuffer((__gm__ int32_t *)sparseIndices);
167	    softmaxMaxGm.SetGlobalBuffer((__gm__ T *)softmaxMax);
168	    softmaxSumGm.SetGlobalBuffer((__gm__ T *)softmaxSum);
169	    if constexpr (SLIT::hasRope) {
170	        queryRopeGm.SetGlobalBuffer((__gm__ Q_ROPE_T *)queryRope);
171	        keyRopeGm.SetGlobalBuffer((__gm__ K_ROPE_T *)keyRope);
172	    }
173	    if (actualSeqLengthsQuery != nullptr) {
174	        actualSeqLengthsQueryGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsQuery, constInfo.bSize);
175	    } else {
176	        actualSeqLengthsQueryGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsQuery, 0);
177	    }
178	    if (actualSeqLengthsKey != nullptr) {
179	        actualSeqLengthsKeyGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsKey, constInfo.bSize);
180	    } else {
181	        actualSeqLengthsKeyGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsKey, 0);
182	    }
183	
184	    // init output global buffer
185	    dQueryIndexGm.SetGlobalBuffer((__gm__ OUT_T *)dQueryIndex);
186	    dKeyIndexGm.SetGlobalBuffer((__gm__ OUT_T *)dKeyIndex);
187	    dWeightGm.SetGlobalBuffer((__gm__ OUT_T *)dWeight);
188	    lossGm.SetGlobalBuffer((__gm__ T *)loss);
189	    lossGm.SetValue(0, 0.0F);
190	    AscendC::DataCacheCleanAndInvalid<T, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT>(
191	        lossGm);
192	    InitWorkspace(workspace);
193	    InitBuffer(pipe);
194	
195	    if ASCEND_IS_AIV {
196	        // InitVecOP
197	        vectorService.InitParams(constInfo, tilingData);
198	        vectorService.InitVector0GM(keyGm,
199	                                    keyRopeGm,
200	                                    keyIndexGm,
201	                                    topKIndexGm,
202	                                    actualSeqLengthsQueryGm,
203	                                    actualSeqLengthsKeyGm,
204	                                    gatherPRes,
205	                                    gatherSYRes);
206	        vectorService.InitVector1GM(bmm1Res,
207	                                    softmaxMaxGm,
208	                                    softmaxSumGm,
209	                                    bmm2Res,
210	                                    weightGm,
211	                                    psySyncGm,
212	                                    lossGm,
213	                                    dWeightGm,
214	                                    reluGm,
215	                                    reluGradRes,
216	                                    actualSeqLengthsQueryGm,
217	                                    actualSeqLengthsKeyGm,
218	                                    lossRes);
219	        vectorService.InitVector2GM(bmm3Res, topKIndexGm, scatterAddRes);
220	    } else if ASCEND_IS_AIC {
221	        // initCubeOP
222	        matmulService.InitParams(constInfo);
223	
224	        matmulService.InitMm1GlobalTensor(queryGm,
225	                                          gatherPRes,
226	                                          queryRopeGm,
227	                                          actualSeqLengthsQueryGm,
228	                                          actualSeqLengthsKeyGm,
229	                                          bmm1Res,
230	                                          dKeyIndex,
231	                                          keyGm,
232	                                          keyRopeGm);
233	        matmulService.InitMm2GlobalTensor(queryIndexGm, gatherSYRes, bmm2Res, keyIndexGm);
234	        matmulService.InitMm5GlobalTensor(reluGradRes, queryIndexGm, bmm3Res, topKIndexGm, scatterAddRes);
235	        matmulService.InitMm6GlobalTensor(reluGradRes, gatherSYRes, dQueryIndexGm);
236	    }
237	}
