239	template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::InitConstInfo()
240	{
241	    if ASCEND_IS_AIV {
242	        constInfo.aivIdx = GetBlockIdx(); // vec:0-47
243	        constInfo.aicIdx = constInfo.aivIdx / 2;
244	        constInfo.subBlockIdx = constInfo.aivIdx % 2;
245	    } else {
246	        constInfo.aicIdx = GetBlockIdx(); // cube:0-23
247	    }
248	
249	    auto &baseInfo = tilingData->baseParams;
250	    constInfo.bSize = baseInfo.bSize;
251	    constInfo.n2Size = baseInfo.n2Size;
252	    constInfo.gSizeQuery = baseInfo.gSizeQuery;
253	    constInfo.gSizeQueryIndex = baseInfo.gSizeQueryIndex;
254	    constInfo.s1Size = baseInfo.s1Size;
255	    constInfo.s2Size = baseInfo.s2Size;
256	    constInfo.kSize = baseInfo.kSize;
257	
258	    constInfo.dSizeQuery = baseInfo.dSizeQuery;
259	    constInfo.dSizeQueryIndex = baseInfo.dSizeQueryIndex;
260	    constInfo.dSizeRope = 64;
261	    constInfo.sparseMode = static_cast<SLISparseMode>(baseInfo.sparseMode);
262	    constInfo.scaleValue = baseInfo.scaleValue;
263	    constInfo.gatherKeySize = constInfo.kSize * (constInfo.dSizeQuery + constInfo.dSizeRope);
264	    constInfo.gatherKeyIndexSize = constInfo.kSize * constInfo.dSizeQueryIndex;
265	    constInfo.s2BaseSize = N_WORKSPACE_SIZE;
266	}
