268	template <typename SLIT>
269	__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::InitWorkspace(__gm__ uint8_t *workspace)
270	{
271	    int64_t pOffset = constInfo.kSize * (constInfo.dSizeQuery + constInfo.dSizeQueryRope) * sizeof(KV_T); // * 2;
272	    int64_t syOffset = constInfo.kSize * constInfo.dSizeQueryIndex * sizeof(KV_T); // * 2;
273	    int64_t bmm1Offset = constInfo.gSizeQuery * constInfo.kSize * sizeof(float); // * 2;
274	    int64_t psySyncSize = constInfo.kSize * sizeof(float) * 2;
275	    int64_t bmm2Offset = constInfo.gSizeQueryIndex * constInfo.kSize * sizeof(float); // * 2;
276	    int64_t reluGradOffset = constInfo.gSizeQueryIndex * constInfo.kSize * sizeof(float); // * 2;
277	    int64_t bmm3Offset = constInfo.kSize * constInfo.dSizeQueryIndex * sizeof(float); // * 2;
278	    int64_t lossOffset = sizeof(float) * 128; // 为了512Byte对齐
279	
280	    int64_t coreTotalOffset =
281	        constInfo.aicIdx * (pOffset * constInfo.gatherKeyDbNum + syOffset * constInfo.gatherKeyIndexDbNum +
282	                            bmm1Offset * 2 + bmm2Offset * 2 + reluGradOffset * 2 + psySyncSize * 2);
283	
284	    int64_t totalOffset =
285	        GetBlockNum() * (pOffset * constInfo.gatherKeyDbNum + syOffset * constInfo.gatherKeyIndexDbNum +
286	                         bmm1Offset * 2 + bmm2Offset * 2 + reluGradOffset * 2 + psySyncSize * 2);
287	
288	    uint64_t offset = 0;
289	    // workspace 按核分, 每个核内不同workspace相邻
290	    gatherPRes.SetGlobalBuffer((__gm__ KV_T *)(workspace + offset + coreTotalOffset));
291	    offset += pOffset * constInfo.gatherKeyDbNum;
292	
293	    gatherSYRes.SetGlobalBuffer((__gm__ KV_T *)(workspace + offset + coreTotalOffset));
294	    offset += syOffset * constInfo.gatherKeyIndexDbNum;
295	
296	    bmm1Res.SetGlobalBuffer((__gm__ MM12_OUT_T *)(workspace + offset + coreTotalOffset));
297	    offset += bmm1Offset * 2;
298	
299	    psySyncGm.SetGlobalBuffer((__gm__ T *)(workspace + offset + coreTotalOffset));
300	    offset += psySyncSize * 2;
301	
302	    bmm2Res.SetGlobalBuffer((__gm__ MM12_OUT_T *)(workspace + offset + coreTotalOffset));
303	    reluGm.SetGlobalBuffer((__gm__ T *)(bmm2Res.GetPhyAddr()));
304	    offset += bmm2Offset * 2;
305	
306	    reluGradRes.SetGlobalBuffer((__gm__ OUT_T *)(workspace + offset + coreTotalOffset));
307	    offset += reluGradOffset * 2;
308	
309	    bmm3Res.SetGlobalBuffer((__gm__ MM3_OUT_T *)(workspace + totalOffset));
310	    totalOffset += bmm3Offset * GetBlockNum() * 2;
311	
312	    lossRes.SetGlobalBuffer((__gm__ T *)(workspace + totalOffset));
313	    totalOffset += lossOffset;
314	
315	    scatterAddRes.SetGlobalBuffer((__gm__ T *)(workspace + totalOffset));
316	    if ASCEND_IS_AIV {
317	        int64_t totalCost = 0;
318	        if constexpr (KV_LAYOUT_T == SLILayout::TND) {
319	            totalCost = actualSeqLengthsKeyGm.GetValue(constInfo.bSize - 1);
320	        } else {
321	            totalCost = constInfo.bSize * constInfo.s2Size;
322	        }
323	
324	        int64_t totalCoreNum = GetBlockNum() * GetTaskRation();
325	        int64_t avgCost = CeilDiv(totalCost, totalCoreNum);
326	
327	        int32_t t2Start = Min(constInfo.aivIdx * avgCost, totalCost);
328	        int32_t t2End = Min(t2Start + avgCost, totalCost);
329	        AscendC::InitOutput(scatterAddRes[t2Start * constInfo.dSizeQueryIndex],
330	                            constInfo.dSizeQueryIndex * (t2End - t2Start),
331	                            static_cast<T>(0));
332	
333	        int64_t offsetBmm3 = constInfo.aivIdx * bmm3Offset / sizeof(float);
334	        AscendC::InitOutput(bmm3Res[offsetBmm3], bmm3Offset / sizeof(float), static_cast<T>(0));
335	        AscendC::InitOutput(lossRes[constInfo.aivIdx], 1, static_cast<T>(0));
336	    }
337	    SyncAll();
338	}
