349	template <typename SLIT>
350	__aicore__ inline int64_t
351	SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::FindBIndex(int64_t bIndex, int64_t curIndex, int64_t &accumulateLen)
352	{
353	    for (int index = bIndex; index < constInfo.bSize; index++) {
354	        int64_t actualLen = this->actualSeqLengthsQueryGm.GetValue(index);
355	        if (curIndex < actualLen) {
356	            return index;
357	        }
358	        accumulateLen = actualLen;
359	    }
360	    return tilingData->multiCoreParams.totalSize >= curIndex ? constInfo.bSize : -1;
361	}
