371	template <typename SLIT>
372	__aicore__ inline int64_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetEndS1Etx(
373	    int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout)
374	{
375	    if (actualSeqLensGm.GetSize() <= 0) {
376	        return defaultLens;
377	    }
378	
379	    if (layout == SLILayout::TND) {
380	        if (bIdx == 0) {
381	            return actualSeqLensGm.GetValue(0);
382	        } else {
383	            return (actualSeqLensGm.GetValue(bIdx) - actualSeqLensGm.GetValue(bIdx - 1));
384	        }
385	    } else {
386	        assert(false, "do not support current layout!\n");
387	        return 0;
388	    }
389	}
