391	template <typename SLIT>
392	__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::CalcMultiCoreOffset(int64_t &bStartIdx,
393	                                                                                              int64_t &s1StartIdx,
394	                                                                                              int64_t &bEndIdx,
395	                                                                                              int64_t &s1EndIdx)
396	{
397	    int64_t actualSum = 0;
398	    int64_t bS1Index = tilingData->multiCoreParams.bS1Index[constInfo.aicIdx];
399	    int64_t bS1EndIndex = constInfo.aicIdx + 1 < optiling::MAX_CORE_NUM
400	                              ? tilingData->multiCoreParams.bS1Index[constInfo.aicIdx + 1]
401	                              : tilingData->multiCoreParams.totalSize;
402	    if constexpr (LAYOUT_T == SLILayout::TND) {
403	        bStartIdx = FindBIndex(0, bS1Index, actualSum);
404	        s1StartIdx = bS1Index - actualSum;
405	        bEndIdx = FindBIndex(bStartIdx, bS1EndIndex - 1, actualSum);
406	        s1EndIdx = bS1EndIndex - actualSum;
407	    } else {
408	        bStartIdx = bS1Index / constInfo.s1Size;
409	        bEndIdx = (bS1EndIndex - 1) / constInfo.s1Size;
410	        s1StartIdx = bS1Index - bStartIdx * constInfo.s1Size;
411	        s1EndIdx = bS1EndIndex - bEndIdx * constInfo.s1Size;
412	    }
413	}
