415	template <typename SLIT> __aicore__ inline int64_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::CalcBS1Loop()
416	{
417	    int64_t maxLoop = 0;
418	    int32_t coreNum = GetBlockNum();
419	    int64_t bS1Index, bS1EndIndex;
420	    for (int32_t aicIdx = 0; aicIdx < coreNum; aicIdx++) {
421	        bS1Index = tilingData->multiCoreParams.bS1Index[aicIdx];
422	        bS1EndIndex = aicIdx + 1 < optiling::MAX_CORE_NUM ? tilingData->multiCoreParams.bS1Index[aicIdx + 1]
423	                                                          : tilingData->multiCoreParams.totalSize;
424	        maxLoop = Max(maxLoop, bS1EndIndex - bS1Index);
425	    }
426	    return maxLoop;
427	}
