438	template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::DeterProcess()
439	{
440	    if ASCEND_IS_AIV {
441	        vectorService.AllocEventID();
442	    } else {
443	        matmulService.AllocEventID();
444	    }
445	    int64_t coreNum = GetBlockNum();
446	    int64_t bS1TotalSize = tilingData->multiCoreParams.totalSize;
447	    int64_t extraLoopTimes = 2;
448	    int64_t actualBS1Sum = 0;
449	    int64_t bIdx = 0;
450	    int64_t s1Idx = 0;
451	    int64_t taskId = 0;
452	    for (int64_t bS1Idx = constInfo.aicIdx; bS1Idx < bS1TotalSize + extraLoopTimes * coreNum; bS1Idx += coreNum) {
453	        if (bS1Idx < bS1TotalSize) {
454	            if constexpr (LAYOUT_T == SLILayout::TND) {
455	                bIdx = FindBIndex(bIdx, bS1Idx, actualBS1Sum);
456	                s1Idx = bS1Idx - actualBS1Sum;
457	            } else {
458	                bIdx = bS1Idx / constInfo.s1Size;
459	                s1Idx = bS1Idx - bIdx * constInfo.s1Size;
460	            }
461	        } else {
462	            bIdx = 0;
463	            s1Idx = bS1TotalSize;
464	        }
465	
466	        GetRunInfo(taskId, bIdx, s1Idx, bS1TotalSize);
467	
468	        SLIGradKLLossRunInfo &runInfoNeg2 = runInfos[(taskId + 1) % 3]; // 上2轮
469	        SLIGradKLLossRunInfo &runInfoNeg1 = runInfos[(taskId + 2) % 3]; // 上1轮
470	        SLIGradKLLossRunInfo &runInfo0 = runInfos[taskId % 3]; // 当前轮
471	
472	        if ASCEND_IS_AIV {
473	            CrossCoreWaitFlag<2, PIPE_MTE3>(14);
474	        } else {
475	            CrossCoreSetFlag<2, PIPE_MTE2>(14);
476	        }
477	
478	        if (runInfo0.isValid) {
479	            if ASCEND_IS_AIV {
480	                vectorService.ProcessVector0(runInfo0); // V0
481	            }
482	        }
483	
484	        if (runInfoNeg1.isValid) {
485	            if ASCEND_IS_AIC {
486	                matmulService.ComputeMm1(runInfoNeg1); // C1
487	                matmulService.ComputeMm2(runInfoNeg1); // C1
488	            }
489	
490	            if ASCEND_IS_AIV {
491	                vectorService.ProcessVector1(runInfoNeg1); // V1
492	            }
493	            if ASCEND_IS_AIC {
494	                matmulService.ComputeMm5(runInfoNeg1); // C2
495	                matmulService.ComputeMm6(runInfoNeg1); // C2
496	            }
497	        }
498	
499	        if (runInfoNeg2.isValid) {
500	            if ASCEND_IS_AIV {
501	                vectorService.ProcessDeterVector2(runInfoNeg2);
502	                runInfoNeg2.isValid = false;
503	            }
504	        }
505	        taskId++;
506	    }
507	
508	    if (constInfo.aicIdx + 1 > bS1TotalSize % coreNum) {
509	        if ASCEND_IS_AIC {
510	            CrossCoreSetFlag<2, PIPE_FIX>(SYNC_C2_TO_V2_SA_FLAG[(taskId - extraLoopTimes) & 1]);
511	        }
512	        if ASCEND_IS_AIV {
513	            SLIGradKLLossRunInfo runInfo;
514	            runInfo.taskId = taskId - extraLoopTimes;
515	            runInfo.taskIdMod2 = runInfo.taskId & 1;
516	            vectorService.ProcessDeterVector2(runInfo);
517	        }
518	    }
519	
520	    if ASCEND_IS_AIV {
521	        vectorService.FreeEventID();
522	    } else {
523	        matmulService.FreeEventID();
524	    }
525	    if ASCEND_IS_AIV {
526	        vector2Service.InitParams(constInfo, tilingData);
527	        vector2Service.InitVector2GM(
528	            scatterAddRes, topKIndexGm, dKeyIndexGm, actualSeqLengthsQueryGm, actualSeqLengthsKeyGm, lossRes, lossGm);
529	        vector2Service.InitBuffers(pipe);
530	    }
531	    SyncAll<false>();
532	    if ASCEND_IS_AIV {
533	        vector2Service.AllocEventID();
534	        vector2Service.ProcessVector2();
535	        vector2Service.FreeEventID();
536	    }
537	}
