539	template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::MainProcess()
540	{
541	    if ASCEND_IS_AIV {
542	        vectorService.AllocEventID();
543	    } else {
544	        matmulService.AllocEventID();
545	    }
546	
547	    int64_t bStartIdx, s1StartIdx, bEndIdx, s1EndIdx;
548	    CalcMultiCoreOffset(bStartIdx, s1StartIdx, bEndIdx, s1EndIdx);
549	
550	    int64_t taskId = 0;
551	    int64_t extraLoopTimes = 0;
552	    for (int64_t bIdx = bStartIdx; bIdx <= bEndIdx; bIdx++) {
553	        bool lastB = (bIdx == bEndIdx);
554	        int64_t s1StartIdxThisBatch = 0;
555	        int64_t s1EndIdxThisBatch = 0;
556	        if constexpr (LAYOUT_T == SLILayout::TND) {
557	            s1StartIdxThisBatch = (bIdx == bStartIdx) ? s1StartIdx : 0;
558	            s1EndIdxThisBatch =
559	                (!lastB) ? GetEndS1Etx(bIdx, constInfo.s1Size, actualSeqLengthsQueryGm, LAYOUT_T) : s1EndIdx;
560	        } else if constexpr (LAYOUT_T == SLILayout::BSND) {
561	            s1StartIdxThisBatch = (bIdx == bStartIdx) ? s1StartIdx : 0;
562	            s1EndIdxThisBatch = (!lastB) ? constInfo.s1Size : s1EndIdx;
563	        }
564	        if (lastB) {
565	            extraLoopTimes = 2; // 最后一个Batch需要额外循环两次，因为preload方式会产生尾巴
566	        }
567	        for (int64_t s1Idx = s1StartIdxThisBatch; s1Idx < s1EndIdxThisBatch + extraLoopTimes; s1Idx++) {
568	            GetRunInfo(taskId, bIdx, s1Idx, s1EndIdxThisBatch);
569	
570	            SLIGradKLLossRunInfo &runInfoNeg2 = runInfos[(taskId + 1) % 3]; // 上2轮
571	            SLIGradKLLossRunInfo &runInfoNeg1 = runInfos[(taskId + 2) % 3]; // 上1轮
572	            SLIGradKLLossRunInfo &runInfo0 = runInfos[taskId % 3]; // 当前轮
573	
574	            if ASCEND_IS_AIV {
575	                CrossCoreWaitFlag<2, PIPE_MTE3>(14);
576	            } else {
577	                CrossCoreSetFlag<2, PIPE_MTE2>(14);
578	            }
579	
580	            if (runInfo0.isValid) {
581	                if ASCEND_IS_AIV {
582	                    vectorService.ProcessVector0(runInfo0); // V0
583	                }
584	            }
585	
586	            if (runInfoNeg1.isValid) {
587	                if ASCEND_IS_AIC {
588	                    matmulService.ComputeMm1(runInfoNeg1); // C1
589	                    matmulService.ComputeMm2(runInfoNeg1); // C1
590	                }
591	
592	                if ASCEND_IS_AIV {
593	                    vectorService.ProcessVector1(runInfoNeg1); // V1
594	                }
595	                if ASCEND_IS_AIC {
596	                    matmulService.ComputeMm5(runInfoNeg1); // C2
597	                    matmulService.ComputeMm6(runInfoNeg1); // C2
598	                }
599	            }
600	
601	            if (runInfoNeg2.isValid) {
602	                if ASCEND_IS_AIV {
603	                    vectorService.ProcessVector2(runInfoNeg2); // V2 ScatterAdd
604	                    runInfoNeg2.isValid = false;
605	                }
606	            }
607	
608	            taskId++;
609	        }
610	    }
611	
612	    if ASCEND_IS_AIV {
613	        vectorService.FreeEventID();
614	    } else {
615	        matmulService.FreeEventID();
616	    }
617	    if ASCEND_IS_AIV {
618	        vector2Service.InitParams(constInfo, tilingData);
619	        vector2Service.InitVector2GM(
620	            scatterAddRes, topKIndexGm, dKeyIndexGm, actualSeqLengthsQueryGm, actualSeqLengthsKeyGm, lossRes, lossGm);
621	        vector2Service.InitBuffers(pipe);
622	    }
623	    SyncAll<false>();
624	    if ASCEND_IS_AIV {
625	        vector2Service.AllocEventID();
626	        vector2Service.ProcessVector2();
627	        vector2Service.FreeEventID();
628	    }
629	}
630	
631	template <typename SLIT>
632	__aicore__ inline int32_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetActualSeqLens(
633	    int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout, int64_t &accumLen)
634	{
635	    if (actualSeqLensGm.GetSize() <= 0) {
636	        return defaultLens;
637	    }
638	
639	    if (layout == SLILayout::TND) {
640	        if (bIdx == 0) {
641	            accumLen = 0;
642	            return actualSeqLensGm.GetValue(0);
643	        } else {
644	            accumLen = actualSeqLensGm.GetValue(bIdx - 1);
645	            return (actualSeqLensGm.GetValue(bIdx) - accumLen);
646	        }
647	    } else {
648	        return 0;
649	    }
650	}
651	
652	template <typename SLIT>
653	__aicore__ inline int32_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetS2SparseLen(int32_t s1Idx,
654	                                                                                            int32_t actualSeqLensQ,
655	                                                                                            int32_t actualSeqLensK,
656	                                                                                            SLISparseMode sparseMode)
657	{
658	    if (sparseMode == SLISparseMode::RightDown) {
659	        return Max(actualSeqLensK - actualSeqLensQ + s1Idx + 1, 0);
660	    } else {
661	        return 0;
662	    }
663	}
664	
665	template <typename SLIT>
666	__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetRunInfo(int64_t taskId,
667	                                                                                     int64_t bIdx,
668	                                                                                     int64_t s1Idx,
669	                                                                                     int64_t s1IdxEnd)
670	{
671	    auto &runInfo = runInfos[taskId % 3];
672	    if (s1Idx >= s1IdxEnd) { // extra循环阶段，不生产任务
673	        runInfo.isValid = false;
674	        return;
675	    }
676	
677	    runInfo.taskId = taskId;
678	    runInfo.taskIdMod2 = taskId & 1;
679	
680	    runInfo.bIdx = bIdx;
681	    runInfo.s1Idx = s1Idx;
682	    if constexpr (LAYOUT_T == SLILayout::TND) {
683	        int32_t actualSeqLensQ =
684	            GetActualSeqLens(runInfo.bIdx, constInfo.s1Size, actualSeqLengthsQueryGm, LAYOUT_T, runInfo.accumS1Idx);
685	        int32_t actualSeqLensK =
686	            GetActualSeqLens(runInfo.bIdx, constInfo.s2Size, actualSeqLengthsKeyGm, KV_LAYOUT_T, runInfo.accumS2Idx);
687	        runInfo.actS1Size = actualSeqLensQ;
688	        runInfo.actS2Size = actualSeqLensK;
689	        runInfo.accumS1Idx += s1Idx;
690	    } else if constexpr (LAYOUT_T == SLILayout::BSND) {
691	        runInfo.actS1Size = constInfo.s1Size;
692	        runInfo.actS2Size = constInfo.s2Size;
693	        runInfo.accumS1Idx = bIdx * constInfo.s1Size + s1Idx;
694	        runInfo.accumS2Idx = bIdx * constInfo.s2Size;
695	    }
696	
697	    runInfo.nRealSizeP = 128;
698	    runInfo.kBaseSize = 2048;
699	    runInfo.nBaseSizeSY = 0;
700	    runInfo.nRealSizeSY = 0;
701	    runInfo.nIdxP = 0;
702	    runInfo.nIdxSY = 0;
703	
704	    runInfo.s2SparseLen = GetS2SparseLen(runInfo.s1Idx, runInfo.actS1Size, runInfo.actS2Size, constInfo.sparseMode);
705	    runInfo.s2RealSize = Min(constInfo.kSize, runInfo.s2SparseLen);
706	
707	    runInfo.kRealSize = runInfo.s2RealSize;
708	    runInfo.kRealSizeAlign8 = (runInfo.kRealSize + 7) >> 3 << 3;
709	    runInfo.s2LoopTimes = CeilDiv(runInfo.s2RealSize, constInfo.s2BaseSize);
710	    runInfo.s2TailSize = (runInfo.s2RealSize % constInfo.s2BaseSize == 0) ? constInfo.s2BaseSize
711	                                                                          : (runInfo.s2RealSize % constInfo.s2BaseSize);
712	
713	    runInfo.kLoopTimes = CeilDiv(runInfo.kRealSize, runInfo.kBaseSize);
714	    runInfo.kTailSize =
715	        (runInfo.kRealSize % runInfo.kBaseSize == 0) ? runInfo.kBaseSize : (runInfo.kRealSize % runInfo.kBaseSize);
716	
717	    if constexpr (LAYOUT_T == SLILayout::TND) {
718	        runInfo.queryTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQuery);
719	        runInfo.queryRopeTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQueryRope);
720	        runInfo.queryIndexTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQueryIndex * constInfo.dSizeQueryIndex;
721	        runInfo.keyTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQuery;
722	        runInfo.keyRopeTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryRope;
723	        runInfo.keyIndexTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryIndex;
724	    } else if constexpr (LAYOUT_T == SLILayout::BSND) {
725	        runInfo.queryTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQuery);
726	        runInfo.queryRopeTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQueryRope);
727	        runInfo.queryIndexTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQueryIndex * constInfo.dSizeQueryIndex;
728	        runInfo.keyTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQuery;
729	        runInfo.keyRopeTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryRope;
730	        runInfo.keyIndexTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryIndex;
731	    }
732	
733	    if constexpr (LAYOUT_T == SLILayout::TND) {
734	        runInfo.topkGmBaseOffset = runInfo.accumS1Idx * constInfo.kSize;
735	    } else {
736	        runInfo.topkGmBaseOffset = runInfo.bIdx * constInfo.s1Size * constInfo.kSize + runInfo.s1Idx * constInfo.kSize;
737	    }
738	
739	    runInfo.calcP = ((runInfo.taskIdMod2 == 0 && constInfo.subBlockIdx == 0) ||
740	                     (runInfo.taskIdMod2 != 0 && constInfo.subBlockIdx != 0));
741	    runInfo.mergeKv = (runInfo.s2SparseLen > constInfo.kSize);
742	    runInfo.isValid = true;
743	}
744	
745	#endif // SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_BASE_H
