 * \brief
 */

#ifndef SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_BASE_H
#define SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_BASE_H

#include "kernel_operator.h"
#include "kernel_operator_list_tensor_intf.h"
#include "kernel_tiling/kernel_tiling.h"
#include "lib/matmul_intf.h"
#include "lib/matrix/matmul/tiling.h"
#include "sparse_lightning_indexer_grad_kl_loss_enhance_common.h"
#include "sparse_lightning_indexer_grad_kl_loss_enhance_tiling.h"
#include "sparse_lightning_indexer_grad_kl_loss_enhance_vector.h"
#include "sparse_lightning_indexer_grad_kl_loss_enhance_vector2.h"
#include "sparse_lightning_indexer_grad_kl_loss_enhance_service_cube.h"

using namespace matmul;
using AscendC::CacheMode;
using AscendC::CrossCoreSetFlag;
using AscendC::CrossCoreWaitFlag;

template <typename SLIT> class SparseLightningIndexerGradKLLossEnhanceBase {
  public:
    // 中间计算数据类型为float，高精度模式
    using T = float;
    using Q_T = typename SLIT::inputQT;
    using KV_T = typename SLIT::inputKT;
    using OUT_T = typename SLIT::outputT;
    using Q_ROPE_T = Q_T;
    using K_ROPE_T = KV_T;
    using MM12_OUT_T = T;
    using MM3_OUT_T = T;

    static constexpr bool hasRope = SLIT::hasRope;
    static constexpr int TEMPLATE_MODE = SLIT::templateMode;
    static constexpr bool deterministic = SLIT::deterministic;
    static constexpr SLITopKRange topKRange = SLIT::topKRange;
    static constexpr SLILayout LAYOUT_T = SLIT::inputQLayout;
    static constexpr SLILayout KV_LAYOUT_T = SLIT::inputKLayout;

    __aicore__ inline SparseLightningIndexerGradKLLossEnhanceBase(){};
    __aicore__ inline void Init(__gm__ uint8_t *query,
                                __gm__ uint8_t *key,
                                __gm__ uint8_t *queryIndex,
                                __gm__ uint8_t *keyIndex,
                                __gm__ uint8_t *weight,
                                __gm__ uint8_t *sparseIndices,
                                __gm__ uint8_t *softmaxMax,
                                __gm__ uint8_t *softmaxSum,
                                __gm__ uint8_t *queryRope,
                                __gm__ uint8_t *keyRope,
                                __gm__ uint8_t *actualSeqLengthsQuery,
                                __gm__ uint8_t *actualSeqLengthsKey,
                                __gm__ uint8_t *dQueryIndex,
                                __gm__ uint8_t *dKeyIndex,
                                __gm__ uint8_t *dWeight,
                                __gm__ uint8_t *loss,
                                __gm__ uint8_t *workspace,
                                const optiling::SparseLightningIndexerGradKLLossEnhanceTilingData *__restrict tiling,
                                TPipe *tPipe);
    __aicore__ inline void InitConstInfo();
    __aicore__ inline void InitBuffer(TPipe *pipe);
    __aicore__ inline void InitWorkspace(__gm__ uint8_t *workspace);
    __aicore__ inline void Process();
    __aicore__ inline void MainProcess();
    __aicore__ inline void DeterProcess();
    __aicore__ inline void GetRunInfo(int64_t taskId, int64_t bIdx, int64_t s1Idx, int64_t s1IdxEnd);

  private:
    __aicore__ inline int32_t GetActualSeqLens(
        int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout, int64_t &accumLen);
    __aicore__ inline int32_t
    GetS2SparseLen(int32_t s1Idx, int32_t actualSeqLensQ, int32_t actualSeqLensK, SLISparseMode sparseMode);
    __aicore__ inline int64_t FindBIndex(int64_t bIndex, int64_t curIndex, int64_t &accumulateLen);
    __aicore__ inline int64_t GetEndS1(int64_t bIdx);
    __aicore__ inline int64_t
    GetEndS1Etx(int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout);
    __aicore__ inline void
    CalcMultiCoreOffset(int64_t &bStartIdx, int64_t &s1StartIdx, int64_t &bEndIdx, int64_t &s1EndIdx);
    __aicore__ inline int64_t CalcBS1Loop();

    TPipe *pipe = nullptr;
    const optiling::SparseLightningIndexerGradKLLossEnhanceTilingData *__restrict tilingData = nullptr;
    SLIGradKLLossConstInfo constInfo;
    SLIGradKLLossRunInfo runInfos[3];

    // vector and cube class
    SLIKLLossVectorService<SLIT> vectorService;
    SLIKLLossVector2Service<SLIT> vector2Service;
    SLITMatmulService<SLIT> matmulService;

    // input GM
    GlobalTensor<Q_T> queryGm, queryIndexGm, weightGm;
    GlobalTensor<KV_T> keyGm, keyIndexGm;
    GlobalTensor<Q_ROPE_T> queryRopeGm;
    GlobalTensor<K_ROPE_T> keyRopeGm;
    GlobalTensor<T> softmaxMaxGm, softmaxSumGm;
    GlobalTensor<int32_t> topKIndexGm;
    GlobalTensor<int64_t> actualSeqLengthsQueryGm, actualSeqLengthsKeyGm;
    // output GM
    GlobalTensor<OUT_T> dQueryIndexGm, dKeyIndexGm, dWeightGm;
    GlobalTensor<T> lossGm;
    // workspace
    GlobalTensor<KV_T> gatherPRes, gatherSYRes;
    GlobalTensor<MM12_OUT_T> bmm1Res, bmm2Res;
    GlobalTensor<T> psySyncGm;
    GlobalTensor<KV_T> reluGradRes;
    GlobalTensor<T> scatterAddRes;
    GlobalTensor<MM3_OUT_T> bmm3Res;
    GlobalTensor<T> reluGm;
    GlobalTensor<T> lossRes;
    // local tensor
    TBuf<> gatherTbuf;
    TBuf<> mm1Tbuf;
    TBuf<> lossSumTBuf;
    TBuf<> mm2TBuf; // 复用 -> mm4 scatterAdd reluGrad
};

template <typename SLIT>
__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::Init(
    __gm__ uint8_t *query,
    __gm__ uint8_t *key,
    __gm__ uint8_t *queryIndex,
    __gm__ uint8_t *keyIndex,
    __gm__ uint8_t *weight,
    __gm__ uint8_t *sparseIndices,
    __gm__ uint8_t *softmaxMax,
    __gm__ uint8_t *softmaxSum,
    __gm__ uint8_t *queryRope,
    __gm__ uint8_t *keyRope,
    __gm__ uint8_t *actualSeqLengthsQuery,
    __gm__ uint8_t *actualSeqLengthsKey,
    __gm__ uint8_t *dQueryIndex,
    __gm__ uint8_t *dKeyIndex,
    __gm__ uint8_t *dWeight,
    __gm__ uint8_t *loss,
    __gm__ uint8_t *workspace,
    const optiling::SparseLightningIndexerGradKLLossEnhanceTilingData *__restrict tiling,
    TPipe *tPipe)
{
    // init tiling data
    pipe = tPipe;
    tilingData = tiling;

    InitConstInfo();

    // init input global buffer
    queryGm.SetGlobalBuffer((__gm__ Q_T *)query);
    keyGm.SetGlobalBuffer((__gm__ KV_T *)key);
    queryIndexGm.SetGlobalBuffer((__gm__ Q_T *)queryIndex);
    keyIndexGm.SetGlobalBuffer((__gm__ KV_T *)keyIndex);
    weightGm.SetGlobalBuffer((__gm__ Q_T *)weight);
    topKIndexGm.SetGlobalBuffer((__gm__ int32_t *)sparseIndices);
    softmaxMaxGm.SetGlobalBuffer((__gm__ T *)softmaxMax);
    softmaxSumGm.SetGlobalBuffer((__gm__ T *)softmaxSum);
    if constexpr (SLIT::hasRope) {
        queryRopeGm.SetGlobalBuffer((__gm__ Q_ROPE_T *)queryRope);
        keyRopeGm.SetGlobalBuffer((__gm__ K_ROPE_T *)keyRope);
    }
    if (actualSeqLengthsQuery != nullptr) {
        actualSeqLengthsQueryGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsQuery, constInfo.bSize);
    } else {
        actualSeqLengthsQueryGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsQuery, 0);
    }
    if (actualSeqLengthsKey != nullptr) {
        actualSeqLengthsKeyGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsKey, constInfo.bSize);
    } else {
        actualSeqLengthsKeyGm.SetGlobalBuffer((__gm__ int64_t *)actualSeqLengthsKey, 0);
    }

    // init output global buffer
    dQueryIndexGm.SetGlobalBuffer((__gm__ OUT_T *)dQueryIndex);
    dKeyIndexGm.SetGlobalBuffer((__gm__ OUT_T *)dKeyIndex);
    dWeightGm.SetGlobalBuffer((__gm__ OUT_T *)dWeight);
    lossGm.SetGlobalBuffer((__gm__ T *)loss);
    lossGm.SetValue(0, 0.0F);
    AscendC::DataCacheCleanAndInvalid<T, AscendC::CacheLine::SINGLE_CACHE_LINE, AscendC::DcciDst::CACHELINE_OUT>(
        lossGm);
    InitWorkspace(workspace);
    InitBuffer(pipe);

    if ASCEND_IS_AIV {
        // InitVecOP
        vectorService.InitParams(constInfo, tilingData);
        vectorService.InitVector0GM(keyGm,
                                    keyRopeGm,
                                    keyIndexGm,
                                    topKIndexGm,
                                    actualSeqLengthsQueryGm,
                                    actualSeqLengthsKeyGm,
                                    gatherPRes,
                                    gatherSYRes);
        vectorService.InitVector1GM(bmm1Res,
                                    softmaxMaxGm,
                                    softmaxSumGm,
                                    bmm2Res,
                                    weightGm,
                                    psySyncGm,
                                    lossGm,
                                    dWeightGm,
                                    reluGm,
                                    reluGradRes,
                                    actualSeqLengthsQueryGm,
                                    actualSeqLengthsKeyGm,
                                    lossRes);
        vectorService.InitVector2GM(bmm3Res, topKIndexGm, scatterAddRes);
    } else if ASCEND_IS_AIC {
        // initCubeOP
        matmulService.InitParams(constInfo);

        matmulService.InitMm1GlobalTensor(queryGm,
                                          gatherPRes,
                                          queryRopeGm,
                                          actualSeqLengthsQueryGm,
                                          actualSeqLengthsKeyGm,
                                          bmm1Res,
                                          dKeyIndex,
                                          keyGm,
                                          keyRopeGm);
        matmulService.InitMm2GlobalTensor(queryIndexGm, gatherSYRes, bmm2Res, keyIndexGm);
        matmulService.InitMm5GlobalTensor(reluGradRes, queryIndexGm, bmm3Res, topKIndexGm, scatterAddRes);
        matmulService.InitMm6GlobalTensor(reluGradRes, gatherSYRes, dQueryIndexGm);
    }
}

template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::InitConstInfo()
{
    if ASCEND_IS_AIV {
        constInfo.aivIdx = GetBlockIdx(); // vec:0-47
        constInfo.aicIdx = constInfo.aivIdx / 2;
        constInfo.subBlockIdx = constInfo.aivIdx % 2;
    } else {
        constInfo.aicIdx = GetBlockIdx(); // cube:0-23
    }

    auto &baseInfo = tilingData->baseParams;
    constInfo.bSize = baseInfo.bSize;
    constInfo.n2Size = baseInfo.n2Size;
    constInfo.gSizeQuery = baseInfo.gSizeQuery;
    constInfo.gSizeQueryIndex = baseInfo.gSizeQueryIndex;
    constInfo.s1Size = baseInfo.s1Size;
    constInfo.s2Size = baseInfo.s2Size;
    constInfo.kSize = baseInfo.kSize;

    constInfo.dSizeQuery = baseInfo.dSizeQuery;
    constInfo.dSizeQueryIndex = baseInfo.dSizeQueryIndex;
    constInfo.dSizeRope = 64;
    constInfo.sparseMode = static_cast<SLISparseMode>(baseInfo.sparseMode);
    constInfo.scaleValue = baseInfo.scaleValue;
    constInfo.gatherKeySize = constInfo.kSize * (constInfo.dSizeQuery + constInfo.dSizeRope);
    constInfo.gatherKeyIndexSize = constInfo.kSize * constInfo.dSizeQueryIndex;
    constInfo.s2BaseSize = N_WORKSPACE_SIZE;
}

template <typename SLIT>
__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::InitWorkspace(__gm__ uint8_t *workspace)
{
    int64_t pOffset = constInfo.kSize * (constInfo.dSizeQuery + constInfo.dSizeQueryRope) * sizeof(KV_T); // * 2;
    int64_t syOffset = constInfo.kSize * constInfo.dSizeQueryIndex * sizeof(KV_T); // * 2;
    int64_t bmm1Offset = constInfo.gSizeQuery * constInfo.kSize * sizeof(float); // * 2;
    int64_t psySyncSize = constInfo.kSize * sizeof(float) * 2;
    int64_t bmm2Offset = constInfo.gSizeQueryIndex * constInfo.kSize * sizeof(float); // * 2;
    int64_t reluGradOffset = constInfo.gSizeQueryIndex * constInfo.kSize * sizeof(float); // * 2;
    int64_t bmm3Offset = constInfo.kSize * constInfo.dSizeQueryIndex * sizeof(float); // * 2;
    int64_t lossOffset = sizeof(float) * 128; // 为了512Byte对齐

    int64_t coreTotalOffset =
        constInfo.aicIdx * (pOffset * constInfo.gatherKeyDbNum + syOffset * constInfo.gatherKeyIndexDbNum +
                            bmm1Offset * 2 + bmm2Offset * 2 + reluGradOffset * 2 + psySyncSize * 2);

    int64_t totalOffset =
        GetBlockNum() * (pOffset * constInfo.gatherKeyDbNum + syOffset * constInfo.gatherKeyIndexDbNum +
                         bmm1Offset * 2 + bmm2Offset * 2 + reluGradOffset * 2 + psySyncSize * 2);

    uint64_t offset = 0;
    // workspace 按核分, 每个核内不同workspace相邻
    gatherPRes.SetGlobalBuffer((__gm__ KV_T *)(workspace + offset + coreTotalOffset));
    offset += pOffset * constInfo.gatherKeyDbNum;

    gatherSYRes.SetGlobalBuffer((__gm__ KV_T *)(workspace + offset + coreTotalOffset));
    offset += syOffset * constInfo.gatherKeyIndexDbNum;

    bmm1Res.SetGlobalBuffer((__gm__ MM12_OUT_T *)(workspace + offset + coreTotalOffset));
    offset += bmm1Offset * 2;

    psySyncGm.SetGlobalBuffer((__gm__ T *)(workspace + offset + coreTotalOffset));
    offset += psySyncSize * 2;

    bmm2Res.SetGlobalBuffer((__gm__ MM12_OUT_T *)(workspace + offset + coreTotalOffset));
    reluGm.SetGlobalBuffer((__gm__ T *)(bmm2Res.GetPhyAddr()));
    offset += bmm2Offset * 2;

    reluGradRes.SetGlobalBuffer((__gm__ OUT_T *)(workspace + offset + coreTotalOffset));
    offset += reluGradOffset * 2;

    bmm3Res.SetGlobalBuffer((__gm__ MM3_OUT_T *)(workspace + totalOffset));
    totalOffset += bmm3Offset * GetBlockNum() * 2;

    lossRes.SetGlobalBuffer((__gm__ T *)(workspace + totalOffset));
    totalOffset += lossOffset;

    scatterAddRes.SetGlobalBuffer((__gm__ T *)(workspace + totalOffset));
    if ASCEND_IS_AIV {
        int64_t totalCost = 0;
        if constexpr (KV_LAYOUT_T == SLILayout::TND) {
            totalCost = actualSeqLengthsKeyGm.GetValue(constInfo.bSize - 1);
        } else {
            totalCost = constInfo.bSize * constInfo.s2Size;
        }

        int64_t totalCoreNum = GetBlockNum() * GetTaskRation();
        int64_t avgCost = CeilDiv(totalCost, totalCoreNum);

        int32_t t2Start = Min(constInfo.aivIdx * avgCost, totalCost);
        int32_t t2End = Min(t2Start + avgCost, totalCost);
        AscendC::InitOutput(scatterAddRes[t2Start * constInfo.dSizeQueryIndex],
                            constInfo.dSizeQueryIndex * (t2End - t2Start),
                            static_cast<T>(0));

        int64_t offsetBmm3 = constInfo.aivIdx * bmm3Offset / sizeof(float);
        AscendC::InitOutput(bmm3Res[offsetBmm3], bmm3Offset / sizeof(float), static_cast<T>(0));
        AscendC::InitOutput(lossRes[constInfo.aivIdx], 1, static_cast<T>(0));
    }
    SyncAll();
}

template <typename SLIT>
__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::InitBuffer(TPipe *pipe)
{
    if ASCEND_IS_AIC {
        matmulService.InitBuffers(pipe);
    } else {
        vectorService.InitBuffers(pipe);
    }
}
template <typename SLIT>
__aicore__ inline int64_t
SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::FindBIndex(int64_t bIndex, int64_t curIndex, int64_t &accumulateLen)
{
    for (int index = bIndex; index < constInfo.bSize; index++) {
        int64_t actualLen = this->actualSeqLengthsQueryGm.GetValue(index);
        if (curIndex < actualLen) {
            return index;
        }
        accumulateLen = actualLen;
    }
    return tilingData->multiCoreParams.totalSize >= curIndex ? constInfo.bSize : -1;
}

template <typename SLIT>
__aicore__ inline int64_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetEndS1(int64_t bIdx)
{
    return constInfo.aicIdx + 1 < optiling::MAX_CORE_NUM
               ? tilingData->multiCoreParams.bS1Index[bIdx + 1]
               : tilingData->multiCoreParams.totalSize - tilingData->multiCoreParams.bS1Index[bIdx];
}

template <typename SLIT>
__aicore__ inline int64_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetEndS1Etx(
    int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout)
{
    if (actualSeqLensGm.GetSize() <= 0) {
        return defaultLens;
    }

    if (layout == SLILayout::TND) {
        if (bIdx == 0) {
            return actualSeqLensGm.GetValue(0);
        } else {
            return (actualSeqLensGm.GetValue(bIdx) - actualSeqLensGm.GetValue(bIdx - 1));
        }
    } else {
        assert(false, "do not support current layout!\n");
        return 0;
    }
}

template <typename SLIT>
__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::CalcMultiCoreOffset(int64_t &bStartIdx,
                                                                                              int64_t &s1StartIdx,
                                                                                              int64_t &bEndIdx,
                                                                                              int64_t &s1EndIdx)
{
    int64_t actualSum = 0;
    int64_t bS1Index = tilingData->multiCoreParams.bS1Index[constInfo.aicIdx];
    int64_t bS1EndIndex = constInfo.aicIdx + 1 < optiling::MAX_CORE_NUM
                              ? tilingData->multiCoreParams.bS1Index[constInfo.aicIdx + 1]
                              : tilingData->multiCoreParams.totalSize;
    if constexpr (LAYOUT_T == SLILayout::TND) {
        bStartIdx = FindBIndex(0, bS1Index, actualSum);
        s1StartIdx = bS1Index - actualSum;
        bEndIdx = FindBIndex(bStartIdx, bS1EndIndex - 1, actualSum);
        s1EndIdx = bS1EndIndex - actualSum;
    } else {
        bStartIdx = bS1Index / constInfo.s1Size;
        bEndIdx = (bS1EndIndex - 1) / constInfo.s1Size;
        s1StartIdx = bS1Index - bStartIdx * constInfo.s1Size;
        s1EndIdx = bS1EndIndex - bEndIdx * constInfo.s1Size;
    }
}

template <typename SLIT> __aicore__ inline int64_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::CalcBS1Loop()
{
    int64_t maxLoop = 0;
    int32_t coreNum = GetBlockNum();
    int64_t bS1Index, bS1EndIndex;
    for (int32_t aicIdx = 0; aicIdx < coreNum; aicIdx++) {
        bS1Index = tilingData->multiCoreParams.bS1Index[aicIdx];
        bS1EndIndex = aicIdx + 1 < optiling::MAX_CORE_NUM ? tilingData->multiCoreParams.bS1Index[aicIdx + 1]
                                                          : tilingData->multiCoreParams.totalSize;
        maxLoop = Max(maxLoop, bS1EndIndex - bS1Index);
    }
    return maxLoop;
}

template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::Process()
{
    if constexpr (deterministic) {
        DeterProcess();
    } else {
        MainProcess();
    }
}

template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::DeterProcess()
{
    if ASCEND_IS_AIV {
        vectorService.AllocEventID();
    } else {
        matmulService.AllocEventID();
    }
    int64_t coreNum = GetBlockNum();
    int64_t bS1TotalSize = tilingData->multiCoreParams.totalSize;
    int64_t extraLoopTimes = 2;
    int64_t actualBS1Sum = 0;
    int64_t bIdx = 0;
    int64_t s1Idx = 0;
    int64_t taskId = 0;
    for (int64_t bS1Idx = constInfo.aicIdx; bS1Idx < bS1TotalSize + extraLoopTimes * coreNum; bS1Idx += coreNum) {
        if (bS1Idx < bS1TotalSize) {
            if constexpr (LAYOUT_T == SLILayout::TND) {
                bIdx = FindBIndex(bIdx, bS1Idx, actualBS1Sum);
                s1Idx = bS1Idx - actualBS1Sum;
            } else {
                bIdx = bS1Idx / constInfo.s1Size;
                s1Idx = bS1Idx - bIdx * constInfo.s1Size;
            }
        } else {
            bIdx = 0;
            s1Idx = bS1TotalSize;
        }

        GetRunInfo(taskId, bIdx, s1Idx, bS1TotalSize);

        SLIGradKLLossRunInfo &runInfoNeg2 = runInfos[(taskId + 1) % 3]; // 上2轮
        SLIGradKLLossRunInfo &runInfoNeg1 = runInfos[(taskId + 2) % 3]; // 上1轮
        SLIGradKLLossRunInfo &runInfo0 = runInfos[taskId % 3]; // 当前轮

        if ASCEND_IS_AIV {
            CrossCoreWaitFlag<2, PIPE_MTE3>(14);
        } else {
            CrossCoreSetFlag<2, PIPE_MTE2>(14);
        }

        if (runInfo0.isValid) {
            if ASCEND_IS_AIV {
                vectorService.ProcessVector0(runInfo0); // V0
            }
        }

        if (runInfoNeg1.isValid) {
            if ASCEND_IS_AIC {
                matmulService.ComputeMm1(runInfoNeg1); // C1
                matmulService.ComputeMm2(runInfoNeg1); // C1
            }

            if ASCEND_IS_AIV {
                vectorService.ProcessVector1(runInfoNeg1); // V1
            }
            if ASCEND_IS_AIC {
                matmulService.ComputeMm5(runInfoNeg1); // C2
                matmulService.ComputeMm6(runInfoNeg1); // C2
            }
        }

        if (runInfoNeg2.isValid) {
            if ASCEND_IS_AIV {
                vectorService.ProcessDeterVector2(runInfoNeg2);
                runInfoNeg2.isValid = false;
            }
        }
        taskId++;
    }

    if (constInfo.aicIdx + 1 > bS1TotalSize % coreNum) {
        if ASCEND_IS_AIC {
            CrossCoreSetFlag<2, PIPE_FIX>(SYNC_C2_TO_V2_SA_FLAG[(taskId - extraLoopTimes) & 1]);
        }
        if ASCEND_IS_AIV {
            SLIGradKLLossRunInfo runInfo;
            runInfo.taskId = taskId - extraLoopTimes;
            runInfo.taskIdMod2 = runInfo.taskId & 1;
            vectorService.ProcessDeterVector2(runInfo);
        }
    }

    if ASCEND_IS_AIV {
        vectorService.FreeEventID();
    } else {
        matmulService.FreeEventID();
    }
    if ASCEND_IS_AIV {
        vector2Service.InitParams(constInfo, tilingData);
        vector2Service.InitVector2GM(
            scatterAddRes, topKIndexGm, dKeyIndexGm, actualSeqLengthsQueryGm, actualSeqLengthsKeyGm, lossRes, lossGm);
        vector2Service.InitBuffers(pipe);
    }
    SyncAll<false>();
    if ASCEND_IS_AIV {
        vector2Service.AllocEventID();
        vector2Service.ProcessVector2();
        vector2Service.FreeEventID();
    }
}

template <typename SLIT> __aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::MainProcess()
{
    if ASCEND_IS_AIV {
        vectorService.AllocEventID();
    } else {
        matmulService.AllocEventID();
    }

    int64_t bStartIdx, s1StartIdx, bEndIdx, s1EndIdx;
    CalcMultiCoreOffset(bStartIdx, s1StartIdx, bEndIdx, s1EndIdx);

    int64_t taskId = 0;
    int64_t extraLoopTimes = 0;
    for (int64_t bIdx = bStartIdx; bIdx <= bEndIdx; bIdx++) {
        bool lastB = (bIdx == bEndIdx);
        int64_t s1StartIdxThisBatch = 0;
        int64_t s1EndIdxThisBatch = 0;
        if constexpr (LAYOUT_T == SLILayout::TND) {
            s1StartIdxThisBatch = (bIdx == bStartIdx) ? s1StartIdx : 0;
            s1EndIdxThisBatch =
                (!lastB) ? GetEndS1Etx(bIdx, constInfo.s1Size, actualSeqLengthsQueryGm, LAYOUT_T) : s1EndIdx;
        } else if constexpr (LAYOUT_T == SLILayout::BSND) {
            s1StartIdxThisBatch = (bIdx == bStartIdx) ? s1StartIdx : 0;
            s1EndIdxThisBatch = (!lastB) ? constInfo.s1Size : s1EndIdx;
        }
        if (lastB) {
            extraLoopTimes = 2; // 最后一个Batch需要额外循环两次，因为preload方式会产生尾巴
        }
        for (int64_t s1Idx = s1StartIdxThisBatch; s1Idx < s1EndIdxThisBatch + extraLoopTimes; s1Idx++) {
            GetRunInfo(taskId, bIdx, s1Idx, s1EndIdxThisBatch);

            SLIGradKLLossRunInfo &runInfoNeg2 = runInfos[(taskId + 1) % 3]; // 上2轮
            SLIGradKLLossRunInfo &runInfoNeg1 = runInfos[(taskId + 2) % 3]; // 上1轮
            SLIGradKLLossRunInfo &runInfo0 = runInfos[taskId % 3]; // 当前轮

            if ASCEND_IS_AIV {
                CrossCoreWaitFlag<2, PIPE_MTE3>(14);
            } else {
                CrossCoreSetFlag<2, PIPE_MTE2>(14);
            }

            if (runInfo0.isValid) {
                if ASCEND_IS_AIV {
                    vectorService.ProcessVector0(runInfo0); // V0
                }
            }

            if (runInfoNeg1.isValid) {
                if ASCEND_IS_AIC {
                    matmulService.ComputeMm1(runInfoNeg1); // C1
                    matmulService.ComputeMm2(runInfoNeg1); // C1
                }

                if ASCEND_IS_AIV {
                    vectorService.ProcessVector1(runInfoNeg1); // V1
                }
                if ASCEND_IS_AIC {
                    matmulService.ComputeMm5(runInfoNeg1); // C2
                    matmulService.ComputeMm6(runInfoNeg1); // C2
                }
            }

            if (runInfoNeg2.isValid) {
                if ASCEND_IS_AIV {
                    vectorService.ProcessVector2(runInfoNeg2); // V2 ScatterAdd
                    runInfoNeg2.isValid = false;
                }
            }

            taskId++;
        }
    }

    if ASCEND_IS_AIV {
        vectorService.FreeEventID();
    } else {
        matmulService.FreeEventID();
    }
    if ASCEND_IS_AIV {
        vector2Service.InitParams(constInfo, tilingData);
        vector2Service.InitVector2GM(
            scatterAddRes, topKIndexGm, dKeyIndexGm, actualSeqLengthsQueryGm, actualSeqLengthsKeyGm, lossRes, lossGm);
        vector2Service.InitBuffers(pipe);
    }
    SyncAll<false>();
    if ASCEND_IS_AIV {
        vector2Service.AllocEventID();
        vector2Service.ProcessVector2();
        vector2Service.FreeEventID();
    }
}

template <typename SLIT>
__aicore__ inline int32_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetActualSeqLens(
    int32_t bIdx, int32_t defaultLens, GlobalTensor<int64_t> &actualSeqLensGm, SLILayout layout, int64_t &accumLen)
{
    if (actualSeqLensGm.GetSize() <= 0) {
        return defaultLens;
    }

    if (layout == SLILayout::TND) {
        if (bIdx == 0) {
            accumLen = 0;
            return actualSeqLensGm.GetValue(0);
        } else {
            accumLen = actualSeqLensGm.GetValue(bIdx - 1);
            return (actualSeqLensGm.GetValue(bIdx) - accumLen);
        }
    } else {
        return 0;
    }
}

template <typename SLIT>
__aicore__ inline int32_t SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetS2SparseLen(int32_t s1Idx,
                                                                                            int32_t actualSeqLensQ,
                                                                                            int32_t actualSeqLensK,
                                                                                            SLISparseMode sparseMode)
{
    if (sparseMode == SLISparseMode::RightDown) {
        return Max(actualSeqLensK - actualSeqLensQ + s1Idx + 1, 0);
    } else {
        return 0;
    }
}

template <typename SLIT>
__aicore__ inline void SparseLightningIndexerGradKLLossEnhanceBase<SLIT>::GetRunInfo(int64_t taskId,
                                                                                     int64_t bIdx,
                                                                                     int64_t s1Idx,
                                                                                     int64_t s1IdxEnd)
{
    auto &runInfo = runInfos[taskId % 3];
    if (s1Idx >= s1IdxEnd) { // extra循环阶段，不生产任务
        runInfo.isValid = false;
        return;
    }

    runInfo.taskId = taskId;
    runInfo.taskIdMod2 = taskId & 1;

    runInfo.bIdx = bIdx;
    runInfo.s1Idx = s1Idx;
    if constexpr (LAYOUT_T == SLILayout::TND) {
        int32_t actualSeqLensQ =
            GetActualSeqLens(runInfo.bIdx, constInfo.s1Size, actualSeqLengthsQueryGm, LAYOUT_T, runInfo.accumS1Idx);
        int32_t actualSeqLensK =
            GetActualSeqLens(runInfo.bIdx, constInfo.s2Size, actualSeqLengthsKeyGm, KV_LAYOUT_T, runInfo.accumS2Idx);
        runInfo.actS1Size = actualSeqLensQ;
        runInfo.actS2Size = actualSeqLensK;
        runInfo.accumS1Idx += s1Idx;
    } else if constexpr (LAYOUT_T == SLILayout::BSND) {
        runInfo.actS1Size = constInfo.s1Size;
        runInfo.actS2Size = constInfo.s2Size;
        runInfo.accumS1Idx = bIdx * constInfo.s1Size + s1Idx;
        runInfo.accumS2Idx = bIdx * constInfo.s2Size;
    }

    runInfo.nRealSizeP = 128;
    runInfo.kBaseSize = 2048;
    runInfo.nBaseSizeSY = 0;
    runInfo.nRealSizeSY = 0;
    runInfo.nIdxP = 0;
    runInfo.nIdxSY = 0;

    runInfo.s2SparseLen = GetS2SparseLen(runInfo.s1Idx, runInfo.actS1Size, runInfo.actS2Size, constInfo.sparseMode);
    runInfo.s2RealSize = Min(constInfo.kSize, runInfo.s2SparseLen);

    runInfo.kRealSize = runInfo.s2RealSize;
    runInfo.kRealSizeAlign8 = (runInfo.kRealSize + 7) >> 3 << 3;
    runInfo.s2LoopTimes = CeilDiv(runInfo.s2RealSize, constInfo.s2BaseSize);
    runInfo.s2TailSize = (runInfo.s2RealSize % constInfo.s2BaseSize == 0) ? constInfo.s2BaseSize
                                                                          : (runInfo.s2RealSize % constInfo.s2BaseSize);

    runInfo.kLoopTimes = CeilDiv(runInfo.kRealSize, runInfo.kBaseSize);
    runInfo.kTailSize =
        (runInfo.kRealSize % runInfo.kBaseSize == 0) ? runInfo.kBaseSize : (runInfo.kRealSize % runInfo.kBaseSize);

    if constexpr (LAYOUT_T == SLILayout::TND) {
        runInfo.queryTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQuery);
        runInfo.queryRopeTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQueryRope);
        runInfo.queryIndexTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQueryIndex * constInfo.dSizeQueryIndex;
        runInfo.keyTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQuery;
        runInfo.keyRopeTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryRope;
        runInfo.keyIndexTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryIndex;
    } else if constexpr (LAYOUT_T == SLILayout::BSND) {
        runInfo.queryTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQuery);
        runInfo.queryRopeTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQuery * (constInfo.dSizeQueryRope);
        runInfo.queryIndexTensorOffset = runInfo.accumS1Idx * constInfo.gSizeQueryIndex * constInfo.dSizeQueryIndex;
        runInfo.keyTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQuery;
        runInfo.keyRopeTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryRope;
        runInfo.keyIndexTensorOffset = runInfo.accumS2Idx * constInfo.dSizeQueryIndex;
    }

    if constexpr (LAYOUT_T == SLILayout::TND) {
        runInfo.topkGmBaseOffset = runInfo.accumS1Idx * constInfo.kSize;
    } else {
        runInfo.topkGmBaseOffset = runInfo.bIdx * constInfo.s1Size * constInfo.kSize + runInfo.s1Idx * constInfo.kSize;
    }

    runInfo.calcP = ((runInfo.taskIdMod2 == 0 && constInfo.subBlockIdx == 0) ||
                     (runInfo.taskIdMod2 != 0 && constInfo.subBlockIdx != 0));
    runInfo.mergeKv = (runInfo.s2SparseLen > constInfo.kSize);
    runInfo.isValid = true;
}

