                                         const GlobalTensor<T> &softmaxSum,
                                         const GlobalTensor<MM12_OUT_T> &bmm2Res,
                                         const GlobalTensor<Q_T> &weight,
                                         const GlobalTensor<T> psySync,
                                         GlobalTensor<T> &loss,
                                         GlobalTensor<OUT_T> &dWeight,
                                         GlobalTensor<T> &reluGm,
                                         GlobalTensor<KV_T> &reluGradRes,
                                         GlobalTensor<int64_t> &actualSeqLengthsQueryGm,
                                         GlobalTensor<int64_t> &actualSeqLengthsKeyGm,
                                         const GlobalTensor<T> &lossRes);
    __aicore__ inline void ProcessVector1(SLIGradKLLossRunInfo &runInfo);

    // =============== vector 2 functions ==============
