    GetKeyRopeGmOffset(int64_t realS2Idx, const SLIGradKLLossRunInfo &runInfo, int64_t s2IdLimit);
    __aicore__ inline int64_t
    GetKeyGmOffset(int64_t realS2Idx, const SLIGradKLLossRunInfo &runInfo, int64_t s2IdLimit, int32_t dValue);
    template <bool gatherRope>
    __aicore__ inline void CopyInKv(int64_t &mte2Size,
                                    int64_t mte3Size,
                                    int64_t mergeMte3Idx,
                                    int64_t realS2Idx1,
                                    int64_t realS2Idx2,
                                    const SLIGradKLLossRunInfo &runInfo,
                                    GlobalTensor<KV_T> srcTensor,
                                    GlobalTensor<KV_T> srcRopeTensor);
    template <event_t IdStart, bool gatherRope>
    __aicore__ inline void CopyOutMrgeResult(int64_t mte2Size,
                                             int64_t mte3Size,
