    __aicore__ inline void GetRunInfo(int64_t taskId, int64_t bIdx, int64_t s1Idx, SLIGradKLLossRunInfo &runInfo);

    // =============== vector common variable ==============
    SLIGradKLLossConstInfo constInfo;
