    // global tensor
    GlobalTensor<KV_T> keyGm;
    GlobalTensor<KV_T> keyIndexGm;
    GlobalTensor<KV_T> keyRopeGm;
    GlobalTensor<int32_t> topKGm;

    GlobalTensor<MM12_OUT_T> bmm1ResGm;
