1185	template <typename SLIT> __aicore__ inline void SLIKLLossVectorService<SLIT>::VectorP(SLIGradKLLossRunInfo &runInfo)
1186	{
1187	    int64_t bmm1Offset = runInfo.taskIdMod2 * constInfo.gSizeQuery * constInfo.kSize;
1188	    int64_t nLoops = CeilDiv(constInfo.gSizeQuery, runInfo.nBaseSizeP);
1189	    int64_t kLoops = CeilDiv(runInfo.kRealSize, K_BASE_SIZE);
1190	
1191	    event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
1192	    LocalTensor<T> mulsResUb[2] = {mm1Tbuf.Get<T>(), mm2TBuf.Get<T>()};
1193	    LocalTensor<uint8_t> sharedTmpBuffer = sharedTBuf.GetWithOffset<uint8_t>(16 * 1024, 0);
1194	    LocalTensor<T> reduceSumPTmpBuffer = sharedTBuf.GetWithOffset<T>(K_BASE_SIZE, 16 * 1024);
1195	
1196	    int64_t softmaxInputSize = CeilDiv(runInfo.nBaseSizeP, 8) * 8;
1197	    LocalTensor<T> softmaxMaxTmp[2] = {sharedTBuf.GetWithOffset<T>(softmaxInputSize, 0),
1198	                                       sharedTBuf.GetWithOffset<T>(softmaxInputSize, softmaxInputSize * sizeof(T))};
1199	    LocalTensor<T> softmaxSumTmp[2] = {sharedTBuf.GetWithOffset<T>(softmaxInputSize, 2 * softmaxInputSize * sizeof(T)),
1200	                                       sharedTBuf.GetWithOffset<T>(softmaxInputSize, 3 * softmaxInputSize * sizeof(T))};
1201	    LocalTensor<T> softmaxMaxUb = sharedTBuf.GetWithOffset<T>(softmaxInputSize * 8, 1024);
1202	    LocalTensor<T> softmaxSumUb = sharedTBuf.GetWithOffset<T>(softmaxInputSize * 8, 2048);
1203	
1204	    uint8_t pingpong = 0;
1205	    for (int64_t n = 0; n < nLoops; n++) { // nLoops=4
1206	        int64_t curNSize = (n == nLoops - 1) ? constInfo.gSizeQuery - (runInfo.nBaseSizeP * n) : runInfo.nBaseSizeP;
1207	        for (int64_t k = 0; k < kLoops; k++) {
1208	            int64_t curKOffset = K_BASE_SIZE * k;
1209	            int64_t curKSize = (k == kLoops - 1) ? runInfo.kRealSize - curKOffset : K_BASE_SIZE;
1210	            int64_t curKSizeAlign8 = CeilDiv(curKSize, 8) * 8;
1211	            int64_t bmm1NOffset = n * runInfo.nBaseSizeP * constInfo.kSize + k * K_BASE_SIZE;
1212	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte2P[pingpong]);
1213	            DataCopyExtParams copyParams = {static_cast<uint16_t>(curNSize),
1214	                                            static_cast<uint32_t>(curKSize * sizeof(T)),
1215	                                            static_cast<uint32_t>((constInfo.kSize - curKSize) * sizeof(T)),
1216	                                            0,
1217	                                            0};
1218	            DataCopyPadExtParams<T> copyPadParams = {false, 0, 0, 0};
1219	            AscendC::DataCopyPad(mulsResUb[pingpong], bmm1ResGm[bmm1Offset + bmm1NOffset], copyParams, copyPadParams);
1220	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1221	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1222	            AscendC::Muls(mulsResUb[pingpong], mulsResUb[pingpong], constInfo.scaleValue, curNSize * curKSizeAlign8);
1223	            PipeBarrier<PIPE_V>();
1224	
1225	            DataCopyExtParams softmaxCopyParams = {
1226	                static_cast<uint16_t>(1),
1227	                static_cast<uint32_t>(runInfo.nBaseSizeP * sizeof(T)), // 8 * 4 = 32Bytes
1228	                static_cast<uint32_t>(0),
1229	                0,
1230	                0};
1231	            DataCopyPadExtParams<T> softmaxCopyPadParams = {false, 0, 0, 0};
1232	            int64_t softmaxInputOffset = 0;
1233	            if constexpr (LAYOUT_T == SLILayout::BSND) {
1234	                softmaxInputOffset = runInfo.bIdx * (constInfo.s1Size * constInfo.gSizeQuery) +
1235	                                     runInfo.s1Idx * constInfo.gSizeQuery + n * runInfo.nBaseSizeP;
1236	            } else if constexpr (LAYOUT_T == SLILayout::TND) {
1237	                softmaxInputOffset = runInfo.accumS1Idx * constInfo.gSizeQuery + n * runInfo.nBaseSizeP;
1238	            }
1239	            AscendC::DataCopyPad(
1240	                softmaxMaxTmp[pingpong], softmaxMaxGm[softmaxInputOffset], softmaxCopyParams, softmaxCopyPadParams);
1241	            AscendC::DataCopyPad(
1242	                softmaxSumTmp[pingpong], softmaxSumGm[softmaxInputOffset], softmaxCopyParams, softmaxCopyPadParams);
1243	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1244	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1245	            AscendC::Brcb(softmaxMaxUb, softmaxMaxTmp[pingpong], curNSize, {1, 8});
1246	            AscendC::Brcb(softmaxSumUb, softmaxSumTmp[pingpong], curNSize, {1, 8});
1247	            PipeBarrier<PIPE_V>();
1248	            LocalTensor<uint8_t> softmaxTmpUb = sharedTBuf.GetWithOffset<uint8_t>(8 * 1024, 0);
1249	            SoftMaxTiling simpleSoftMaxTilingInfo = tilingData->vectorParams.simpleSoftmaxPTilingData;
1250	            AscendC::SimpleSoftMax<T>(mulsResUb[pingpong],
1251	                                      softmaxSumUb,
1252	                                      softmaxMaxUb,
1253	                                      mulsResUb[pingpong],
1254	                                      softmaxTmpUb,
1255	                                      simpleSoftMaxTilingInfo,
1256	                                      {static_cast<uint32_t>(curNSize),
1257	                                       static_cast<uint32_t>(curKSizeAlign8),
1258	                                       static_cast<uint32_t>(curNSize),
1259	                                       static_cast<uint32_t>(curKSize)});
1260	            PipeBarrier<PIPE_V>();
1261	            uint32_t reduceShape[] = {static_cast<uint32_t>(curNSize), static_cast<uint32_t>(curKSizeAlign8)};
1262	            AscendC::ReduceSum<T, AscendC::Pattern::Reduce::RA, true>(
1263	                reduceSumPTmpBuffer, mulsResUb[pingpong], sharedTmpBuffer, reduceShape, true);
1264	            PipeBarrier<PIPE_V>();
1265	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte2P[pingpong]);
1266	            if (n == 0) {
1267	                AscendC::DataCopy(reduceSumPResUb[curKOffset], reduceSumPTmpBuffer, curKSizeAlign8);
1268	            } else {
1269	                AscendC::Add(
1270	                    reduceSumPResUb[curKOffset], reduceSumPResUb[curKOffset], reduceSumPTmpBuffer, curKSizeAlign8);
1271	            }
1272	            PipeBarrier<PIPE_V>();
1273	            pingpong = 1 - pingpong;
1274	        }
1275	    }
1276	    PipeBarrier<PIPE_V>();
1277	    float gRec = 1.0f / static_cast<float>(static_cast<int64_t>(constInfo.gSizeQuery));
1278	    AscendC::Muls(reduceSumPResUb, reduceSumPResUb, gRec, constInfo.kSize);
1279	    PipeBarrier<PIPE_V>();
1280	    event_t eventVToMte3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
1281	    AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
1282	    AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
1283	    AscendC::DataCopy(psySyncGm, reduceSumPResUb, constInfo.kSize);
1284	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1285	}
