1288	__aicore__ inline void SLIKLLossVectorService<SLIT>::PreloadWeight(SLIGradKLLossRunInfo &runInfo)
1289	{
1290	    event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
1291	    int64_t weightOffset = 0;
1292	    if constexpr (LAYOUT_T == SLILayout::BSND) {
1293	        weightOffset =
1294	            runInfo.bIdx * (constInfo.s1Size * constInfo.gSizeQueryIndex) + runInfo.s1Idx * constInfo.gSizeQueryIndex;
1295	    } else if constexpr (LAYOUT_T == SLILayout::TND) {
1296	        weightOffset = runInfo.accumS1Idx * constInfo.gSizeQueryIndex;
1297	    }
1298	    int64_t weightDBOffset = runInfo.taskIdMod2 * AlignTo(constInfo.gSizeQueryIndex, static_cast<uint32_t>(16));
1299	    // weight 可以常驻, 所以直接搬运, 减少搬运切片
1300	
1301	    AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte2Weight[runInfo.taskIdMod2]);
1302	    if (constInfo.gSizeQueryIndex % N_QUERY_INDEX_SPECIAL_2 != 0) {
1303	        DataCopyExtParams copyParams = {1, static_cast<uint32_t>(constInfo.gSizeQueryIndex * sizeof(KV_T)), 0, 0, 0};
1304	        DataCopyPadExtParams<KV_T> copyPadParams = {true, 0, (uint8_t)(N_QUERY_INDEX_SPECIAL), 0.0};
1305	        AscendC::DataCopyPad(weightInUb[weightDBOffset], weightGm[weightOffset], copyParams, copyPadParams);
1306	    } else {
1307	        AscendC::DataCopy(weightInUb[weightDBOffset], weightGm[weightOffset], constInfo.gSizeQueryIndex);
1308	    }
1309	    AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1310	    AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1311	    AscendC::Cast(
1312	        weightUb[weightDBOffset], weightInUb[weightDBOffset], AscendC::RoundMode::CAST_NONE, constInfo.gSizeQueryIndex);
1313	    AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte2Weight[runInfo.taskIdMod2]);
1314	    PipeBarrier<PIPE_V>();
1315	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV);
1316	}
