1318	template <typename SLIT> __aicore__ inline void SLIKLLossVectorService<SLIT>::VectorSy(SLIGradKLLossRunInfo &runInfo)
1319	{
1320	    {
1321	        // weight UB cast To weight.GetValue and release eventID
1322	        event_t eventIdVToS = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_S));
1323	        AscendC::SetFlag<AscendC::HardEvent::V_S>(eventIdVToS);
1324	        AscendC::WaitFlag<AscendC::HardEvent::V_S>(eventIdVToS);
1325	    }
1326	    // 核内保留一份BS1Idx
1327	    int64_t realKSize = runInfo.s2RealSize; // int64_t &realKSize = runInfo.s2RealSize;
1328	    int64_t realKSizeAlign = CeilDiv(realKSize, 8) * 8;
1329	
1330	    // 切B, S1做循环, bmm2 单次存储 [N1_INDEX, TopK] 大小的数据块
1331	    // 为了softmax K轴尽量不切分, 只能在N1方向上切
1332	    int64_t bmm2ResSize = constInfo.gSizeQueryIndex * constInfo.kSize; //  sizeof(float)
1333	    int64_t bmm2ResOffset = runInfo.taskIdMod2 * bmm2ResSize;
1334	    // relu无法复用LocalTensor 所以再 8/ 2 = 4行
1335	    int64_t nSplitSize = ubAllocPolicy.mm2UbSize / constInfo.kSize / sizeof(float);
1336	    // 一个Cube 做 G 行, 分给两个Vector, 每个做 G / 2 的大小
1337	    int64_t nLoopSize = CeilDiv(constInfo.gSizeQueryIndex, nSplitSize);
1338	    AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1339	    for (int64_t n = 0; n < nLoopSize; n++) {
1340	        int64_t bmm2Offset = n * nSplitSize * constInfo.kSize; // 4 * 2048
1341	        DataCopyExtParams copyBmm2Params = {static_cast<uint16_t>(nSplitSize),
1342	                                            static_cast<uint32_t>(realKSize * sizeof(T)),
1343	                                            static_cast<uint32_t>((constInfo.kSize - realKSize) * sizeof(T)),
1344	                                            0,
1345	                                            0};
1346	        DataCopyPadExtParams<T> copyBmm2PadParams = {true, 0, (uint8_t)(realKSizeAlign - realKSize), 0.0};
1347	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1348	        AscendC::DataCopyPad<T>(reluResUb, bmm2ResGm[bmm2ResOffset + bmm2Offset], copyBmm2Params, copyBmm2PadParams);
1349	        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV4SY);
1350	        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventIdMte2ToV4SY);
1351	        int64_t weightOffset = !constInfo.subBlockIdx * AlignTo(constInfo.gSizeQueryIndex, static_cast<uint32_t>(16));
1352	        for (int32_t i = 0; i < nSplitSize; i++) {
1353	            float weightValue = weightUb[weightOffset].GetValue(n * nSplitSize + i);
1354	            int64_t mulOffset = i * realKSizeAlign;
1355	            event_t eventIdSToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_V));
1356	            AscendC::SetFlag<AscendC::HardEvent::S_V>(eventIdSToV);
1357	            AscendC::WaitFlag<AscendC::HardEvent::S_V>(eventIdSToV);
1358	            AscendC::Muls<T>(reluResUb[mulOffset], reluResUb[mulOffset], weightValue, realKSizeAlign);
1359	        }
1360	        PipeBarrier<PIPE_V>();
1361	
1362	        LocalTensor<T> reduceUb = nSplitSize > 1 ? reduceSumYResTmpBuffer : reluResUb;
1363	        if (nSplitSize > 1) {
1364	            // 使用高阶API做自选维度的reduce 不支持源操作数与目的操作数地址重叠。不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。
1365	            uint32_t reduceShape[] = {static_cast<uint32_t>(nSplitSize), static_cast<uint32_t>(realKSizeAlign)};
1366	            constexpr bool isReuse = true;
1367	            AscendC::ReduceSum<T, AscendC::Pattern::Reduce::RA, isReuse>(
1368	                reduceUb, reluResUb, reduceSumTmpBuffer, reduceShape, true);
1369	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1370	            PipeBarrier<PIPE_V>();
1371	        }
1372	
1373	        if (n == 0) {
1374	            AscendC::DataCopy(reduceSumYResUb, reduceUb, realKSizeAlign);
1375	        } else {
1376	            AscendC::Add(reduceSumYResUb, reduceSumYResUb, reduceUb, realKSizeAlign);
1377	        }
1378	
1379	        if (nSplitSize == 1) {
1380	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1381	        }
1382	        PipeBarrier<PIPE_V>();
1383	    }
1384	
1385	    LocalTensor<T> maxTmpBuffer;
1386	    LocalTensor<T> sumTmpBuffer;
1387	    LocalTensor<T> sftTmpBuffer;
1388	
1389	    maxTmpBuffer = sharedTBuf.Get<T>();
1390	    sumTmpBuffer = sharedTBuf.Get<T>()[8];
1391	    sftTmpBuffer = sharedTBuf.Get<T>()[16];
1392	
1393	    ReduceMax<T>(maxTmpBuffer, reduceSumYResUb, sftTmpBuffer, realKSize, 0);
1394	    PipeBarrier<PIPE_V>();
1395	
1396	    AscendC::Brcb(maxTmpBuffer, maxTmpBuffer, 1, {1, 8});
1397	    PipeBarrier<PIPE_V>();
1398	
1399	    Sub(reduceSumYResUb, reduceSumYResUb, maxTmpBuffer, 64, (realKSizeAlign + 63) / 64, {1, 1, 0, 8, 8, 0});
1400	    PipeBarrier<PIPE_V>();
1401	
1402	    Exp(reduceSumYResUb, reduceSumYResUb, realKSize);
1403	    PipeBarrier<PIPE_V>();
1404	
1405	    ReduceSum<T>(sumTmpBuffer, reduceSumYResUb, sftTmpBuffer, realKSize);
1406	    PipeBarrier<PIPE_V>();
1407	
1408	    AscendC::Brcb(sumTmpBuffer, sumTmpBuffer, 1, {1, 8});
1409	    PipeBarrier<PIPE_V>();
1410	
1411	    Div(reduceSumYResUb, reduceSumYResUb, sumTmpBuffer, 64, (realKSizeAlign + 63) / 64, {1, 1, 0, 8, 8, 0});
1412	    PipeBarrier<PIPE_V>();
1413	    DataCopyExtParams copyParams = {1, static_cast<uint32_t>(realKSize * sizeof(float)), 0, 0, 0};
1414	    event_t eventVToMte3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
1415	    AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
1416	    AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(eventVToMte3);
1417	    AscendC::DataCopyPad(psySyncGm[constInfo.kSize], reduceSumYResUb, copyParams);
1418	    AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1419	}
