1421	template <typename SLIT>
1422	__aicore__ inline void SLIKLLossVectorService<SLIT>::ReLUGrad(LocalTensor<KV_T> &reluGradOutTensor,
1423	                                                              LocalTensor<T> &ReLuTensor,
1424	                                                              LocalTensor<T> &subResTensor,
1425	                                                              int32_t kRealSize,
1426	                                                              int32_t kRealSizeAlign8,
1427	                                                              SLIGradKLLossRunInfo &runInfo)
1428	{
1429	    // maskTensor需要创建  subResTensor：mul之后的结果
1430	    LocalTensor<T> maskUb = this->maskBuf.template Get<T>();
1431	    CompareScalar(maskUb, subResTensor, static_cast<T>(0.0), AscendC::CMPMODE::GT, K_BASE_SIZE);
1432	    PipeBarrier<PIPE_V>();
1433	    // UB 新建了一个 maskBuffer
1434	    Select(ReLuTensor,
1435	           maskUb,
1436	           ReLuTensor,
1437	           static_cast<T>(0.0),
1438	           AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE,
1439	           kRealSizeAlign8);
1440	    PipeBarrier<PIPE_V>();
1441	    Cast(reluGradOutTensor, ReLuTensor, AscendC::RoundMode::CAST_ROUND, kRealSizeAlign8);
1442	    PipeBarrier<PIPE_V>();
1443	}
