1445	template <typename SLIT>
1446	__aicore__ inline void SLIKLLossVectorService<SLIT>::DataCopyReluRes(LocalTensor<T> &reluResTensor,
1447	                                                                     GlobalTensor<T> &reluGm,
1448	                                                                     int32_t kRealSize,
1449	                                                                     int32_t kRealSizeAlign8,
1450	                                                                     int64_t reluResOffset)
1451	{
1452	    constexpr static int32_t blockSize = blockBytes / sizeof(T);
1453	    if (likely(kRealSizeAlign8 == kRealSize)) {
1454	        DataCopy(reluResTensor, reluGm[reluResOffset], kRealSize);
1455	    } else {
1456	        DataCopyParams dataCopyParams;
1457	        DataCopyPadParams dataCopyPadParams;
1458	        dataCopyParams.blockCount = 1;
1459	        dataCopyParams.dstStride = 0;
1460	        dataCopyParams.srcStride = 0;
1461	        dataCopyParams.blockLen = kRealSize * sizeof(T);
1462	        dataCopyPadParams.rightPadding = kRealSizeAlign8 - kRealSize;
1463	        dataCopyPadParams.paddingValue = 0;
1464	        DataCopyPad(reluResTensor, reluGm[reluResOffset], dataCopyParams, dataCopyPadParams);
1465	    }
1466	}
