1468	template <typename SLIT>
1469	__aicore__ inline void SLIKLLossVectorService<SLIT>::VectorDwDqDk(SLIGradKLLossRunInfo &runInfo, int32_t kLoopIdx)
1470	{
1471	    LocalTensor<T> v1TmpUb = v1TmpTBuf.template Get<T>();
1472	    LocalTensor<T> reluResUbPingPong[2] = {mm2TBuf.template Get<T>(), mm2TBuf.template Get<T>()[2048]};
1473	    LocalTensor<T> reduceSumPUbSingleK, reduceSumYUbSingleK;
1474	    LocalTensor<T> weightTensor = weightTBuf.template Get<T>();
1475	    LocalTensor<KV_T> reluGradUbPingPong[2] = {mm2TBuf.template Get<KV_T>()[8192], mm2TBuf.template Get<KV_T>()[10240]};
1476	    LocalTensor<uint8_t> tmpUb = sharedTBuf.template Get<uint8_t>()[8192];
1477	    LocalTensor<T> mulLeftUb = sharedTBuf.template Get<T>();
1478	    LocalTensor<T> reduceSumPrevResUb = this->dwTBuf.template Get<T>();
1479	    LocalTensor<KV_T> dwOutTensor = this->dwTBuf.template Get<KV_T>();
1480	    event_t vToMte2PingPong[2] = {event_t(6), event_t(7)};
1481	    event_t mte2ToV = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
1482	    event_t vToMte3 = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE3>());
1483	    event_t mte3ToVPing = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE3_V>());
1484	    event_t mte3ToVPong = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE3_V>());
1485	    event_t mte3ToVPingPong[2] = {mte3ToVPing, mte3ToVPong};
1486	
1487	    int64_t kLoopOffset = kLoopIdx * K_BASE_SIZE;
1488	    int32_t kRealSize = (kLoopIdx == runInfo.kLoopTimes - 1) ? runInfo.kTailSize : K_BASE_SIZE;
1489	    int32_t kRealSizeAlign8 = BlockAlign<T>(kRealSize);
1490	
1491	    AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(eventIdVToMte24SY);
1492	    if (runInfo.calcP) {
1493	        reduceSumPUbSingleK = resPSYTBuf.Get<T>()[kLoopOffset];
1494	        reduceSumYUbSingleK = mm2TBuf.template Get<T>()[6144];
1495	        WaitFlag<HardEvent::V_MTE2>(eventIdVToMte24SY);
1496	        DataCopyReluRes(reduceSumYUbSingleK, psySyncOtherGm, kRealSize, kRealSizeAlign8, constInfo.kSize + kLoopOffset);
1497	    } else {
1498	        reduceSumPUbSingleK = mm2TBuf.template Get<T>()[6144];
1499	        reduceSumYUbSingleK = resPSYTBuf.Get<T>()[kLoopOffset];
1500	        WaitFlag<HardEvent::V_MTE2>(eventIdVToMte24SY);
1501	        DataCopyReluRes(reduceSumPUbSingleK, psySyncOtherGm, kRealSize, kRealSizeAlign8, kLoopOffset);
1502	    }
1503	
1504	    SetFlag<HardEvent::MTE2_V>(mte2ToV);
1505	    WaitFlag<HardEvent::MTE2_V>(mte2ToV);
1506	
1507	    Sub(v1TmpUb, reduceSumYUbSingleK, reduceSumPUbSingleK, kRealSize);
1508	    PipeBarrier<PIPE_V>();
1509	    SumParams sumParams;
1510	    sumParams.outter = 1;
1511	    sumParams.inner = kRealSizeAlign8;
1512	    sumParams.n = kRealSize;
1513	
1514	    DataCopyParams dataCopyReluGradParams;
1515	    dataCopyReluGradParams.blockLen = kRealSize * sizeof(KV_T);
1516	    dataCopyReluGradParams.srcStride = 0;
1517	    dataCopyReluGradParams.blockCount = 1;
1518	    dataCopyReluGradParams.dstStride = 0;
1519	
1520	    int64_t subBlockGQueryIndexOffset = constInfo.subBlockIdx * (constInfo.gSizeQueryIndex >> 1);
1521	    int64_t reluGmOffset =
1522	        (runInfo.taskIdMod2 * constInfo.gSizeQueryIndex + subBlockGQueryIndexOffset) * constInfo.kSize + kLoopOffset;
1523	    int64_t weightOffset = runInfo.taskIdMod2 * AlignTo(constInfo.gSizeQueryIndex, static_cast<uint32_t>(16));
1524	    SetFlag<HardEvent::MTE3_V>(mte3ToVPingPong[0]);
1525	    SetFlag<HardEvent::MTE3_V>(mte3ToVPingPong[1]);
1526	    SetFlag<HardEvent::V_MTE2>(vToMte2PingPong[0]);
1527	    SetFlag<HardEvent::V_MTE2>(vToMte2PingPong[1]);
1528	    for (size_t nIdx = 0; nIdx < constInfo.gSizeQueryIndex >> 1; nIdx++) {
1529	        uint8_t pingPong = nIdx & 1;
1530	        WaitFlag<HardEvent::V_MTE2>(vToMte2PingPong[pingPong]);
1531	        int64_t reluResOffset = reluGmOffset + nIdx * constInfo.kSize; // ((kRealSize + 15) / 16 * 16);
1532	        DataCopyReluRes(reluResUbPingPong[pingPong], reluGm, kRealSize, kRealSizeAlign8, reluResOffset);
1533	
1534	        SetFlag<HardEvent::MTE2_V>(mte2ToV);
1535	        WaitFlag<HardEvent::MTE2_V>(mte2ToV);
1536	        Mul(mulLeftUb, v1TmpUb, reluResUbPingPong[pingPong], kRealSizeAlign8);
1537	        PipeBarrier<PIPE_V>();
1538	
1539	        if (kLoopIdx == 0) {
1540	            // 首轮直接输出到dwUb上
1541	            AscendC::Sum(reduceSumPrevResUb[nIdx * 16], mulLeftUb, tmpUb, sumParams);
1542	        } else {
1543	            AscendC::Sum(reduceSumDwResUb[nIdx * 16], mulLeftUb, tmpUb, sumParams);
1544	        }
1545	        PipeBarrier<PIPE_V>();
1546	
1547	        Muls(mulLeftUb,
1548	             v1TmpUb,
1549	             weightTensor.GetValue(nIdx + weightOffset + subBlockGQueryIndexOffset),
1550	             kRealSizeAlign8);
1551	        PipeBarrier<PIPE_V>();
1552	        WaitFlag<HardEvent::MTE3_V>(mte3ToVPingPong[pingPong]);
1553	        ReLUGrad(
1554	            reluGradUbPingPong[pingPong], mulLeftUb, reluResUbPingPong[pingPong], kRealSize, kRealSizeAlign8, runInfo);
1555	        SetFlag<HardEvent::V_MTE2>(vToMte2PingPong[pingPong]);
1556	
1557	        SetFlag<HardEvent::V_MTE3>(vToMte3);
1558	        WaitFlag<HardEvent::V_MTE3>(vToMte3);
1559	        DataCopyPad(reluGradResGm[reluResOffset], reluGradUbPingPong[pingPong], dataCopyReluGradParams);
1560	        SetFlag<HardEvent::MTE3_V>(mte3ToVPingPong[pingPong]);
1561	    }
1562	    if (kLoopIdx > 0) {
1563	        PipeBarrier<PIPE_V>();
1564	        Add(reduceSumPrevResUb, reduceSumPrevResUb, reduceSumDwResUb, constInfo.gSizeQueryIndex * 16);
1565	    }
1566	    WaitFlag<HardEvent::MTE3_V>(mte3ToVPingPong[0]);
1567	    WaitFlag<HardEvent::MTE3_V>(mte3ToVPingPong[1]);
1568	    WaitFlag<HardEvent::V_MTE2>(vToMte2PingPong[0]);
1569	    WaitFlag<HardEvent::V_MTE2>(vToMte2PingPong[1]);
1570	
1571	    if (kLoopIdx == runInfo.kLoopTimes - 1) {
1572	        PipeBarrier<PIPE_V>();
1573	        Cast(dwOutTensor, reduceSumPrevResUb, AscendC::RoundMode::CAST_ROUND, constInfo.gSizeQueryIndex * 16);
1574	        SetFlag<HardEvent::V_MTE3>(vToMte3);
1575	        WaitFlag<HardEvent::V_MTE3>(vToMte3);
1576	
1577	        // 拷出到GM
1578	        DataCopyParams dataCopyParams;
1579	        dataCopyParams.blockLen = sizeof(KV_T);
1580	        dataCopyParams.srcStride = 0;
1581	        dataCopyParams.blockCount = constInfo.gSizeQueryIndex >> 1;
1582	        dataCopyParams.dstStride = 0;
1583	        if constexpr (LAYOUT_T == SLILayout::BSND) {
1584	            DataCopyPad(dWeightGm[runInfo.bIdx * (constInfo.s1Size * constInfo.gSizeQueryIndex) +
1585	                                  runInfo.s1Idx * constInfo.gSizeQueryIndex + subBlockGQueryIndexOffset],
1586	                        dwOutTensor,
1587	                        dataCopyParams);
1588	        } else if constexpr (LAYOUT_T == SLILayout::TND) {
1589	            DataCopyPad(this->dWeightGm[runInfo.accumS1Idx * constInfo.gSizeQueryIndex + subBlockGQueryIndexOffset],
1590	                        dwOutTensor,
1591	                        dataCopyParams);
1592	        }
1593	    }
1594	
1595	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::MTE2_V>(mte2ToV);
1596	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::V_MTE3>(vToMte3);
1597	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::MTE3_V>(mte3ToVPing);
1598	    GetTPipePtr()->ReleaseEventID<AscendC::HardEvent::MTE3_V>(mte3ToVPong);
1599	}
