1601	template <typename SLIT>
1602	__aicore__ inline void SLIKLLossVectorService<SLIT>::VectorLoss(SLIGradKLLossRunInfo &runInfo, int32_t kLoopIdx)
1603	{
1604	    bool isLastBasicBlock = kLoopIdx == runInfo.kLoopTimes - 1;
1605	    int64_t realKSize = isLastBasicBlock ? runInfo.kTailSize : K_BASE_SIZE;
1606	    int32_t v0RealKSizeAlign = BlockAlign<T>(CeilDiv(realKSize, 2));
1607	    int32_t v0RealKSize = realKSize;
1608	    if (realKSize > 8) {
1609	        v0RealKSize = v0RealKSizeAlign;
1610	    }
1611	    int32_t v1RealKSize = Max(realKSize - v0RealKSizeAlign, 0);
1612	    int32_t v1RealKSizeAlign = BlockAlign<T>(v1RealKSize);
1613	
1614	    int32_t vRealKSize, vRealKSizeAlign;
1615	    int64_t kLoopOffset = kLoopIdx * K_BASE_SIZE;
1616	    int64_t coreOffset = 0;
1617	    if (constInfo.subBlockIdx == 0) {
1618	        vRealKSize = v0RealKSize;
1619	        vRealKSizeAlign = v0RealKSizeAlign;
1620	    } else {
1621	        vRealKSize = v1RealKSize;
1622	        vRealKSizeAlign = v1RealKSizeAlign;
1623	        coreOffset += v0RealKSizeAlign;
1624	    }
1625	
1626	    int64_t calcSize = vRealKSize;
1627	    int64_t calcSizeAlign = vRealKSizeAlign;
1628	    const float MIN_VALUE = 1e-8;
1629	    LocalTensor<T> reduceSumPTmpBuffer = sharedTBuf.GetWithOffset<T>(4 * 1024, 0);
1630	    LocalTensor<uint8_t> sharedTmpBuffer = sharedTBuf.GetWithOffset<uint8_t>(8 * 1024, 4 * 1024);
1631	    LocalTensor<T> vecTmpUb;
1632	    LocalTensor<T> lossSumUb;
1633	    LocalTensor<T> tmpLossUb;
1634	    if (constInfo.subBlockIdx) {
1635	        vecTmpUb = v1TmpTBuf.GetWithOffset<T>(4 * 1024, 4 * 1024);
1636	        lossSumUb = lossSumTBuf.GetWithOffset<T>(8, 32);
1637	        tmpLossUb = sharedTBuf.GetWithOffset<T>(8, 12 * 1024 + 32);
1638	    } else {
1639	        vecTmpUb = v1TmpTBuf.GetWithOffset<T>(4 * 1024, 0);
1640	        lossSumUb = lossSumTBuf.GetWithOffset<T>(8, 0);
1641	        tmpLossUb = sharedTBuf.GetWithOffset<T>(8, 12 * 1024);
1642	    }
1643	
1644	    if (vRealKSize != 0) {
1645	        LocalTensor<T> reduceSumPTmpUb, reduceSumYResTmpUb;
1646	        if (runInfo.calcP) { // 当前核做的是VectorP
1647	            reduceSumPTmpUb = resPSYTBuf.Get<T>();
1648	            reduceSumPTmpUb = reduceSumPTmpUb[kLoopOffset + coreOffset];
1649	            reduceSumYResTmpUb = mm2TBuf.template Get<T>()[6144 + coreOffset];
1650	        } else { // 当前核做的是VectorSY
1651	            reduceSumPTmpUb = mm2TBuf.template Get<T>()[6144 + coreOffset];
1652	            reduceSumYResTmpUb = resPSYTBuf.Get<T>();
1653	            reduceSumYResTmpUb = reduceSumYResTmpUb[kLoopOffset + coreOffset];
1654	        }
1655	        PipeBarrier<PIPE_V>();
1656	        AscendC::Maxs<T>(reduceSumPTmpUb, reduceSumPTmpUb, MIN_VALUE, calcSize);
1657	        PipeBarrier<PIPE_V>();
1658	        AscendC::Maxs<T>(reduceSumYResTmpUb, reduceSumYResTmpUb, MIN_VALUE, calcSize);
1659	        PipeBarrier<PIPE_V>();
1660	
1661	        AscendC::Log(reduceSumPTmpBuffer, reduceSumPTmpUb, calcSize);
1662	        AscendC::Log(reduceSumYResTmpUb, reduceSumYResTmpUb, calcSize);
1663	        PipeBarrier<PIPE_V>();
1664	        AscendC::Sub(vecTmpUb, reduceSumPTmpBuffer, reduceSumYResTmpUb, calcSize);
1665	        PipeBarrier<PIPE_V>();
1666	        AscendC::Mul(vecTmpUb, vecTmpUb, reduceSumPTmpUb, calcSize);
1667	        PipeBarrier<PIPE_V>();
1668	        if (kLoopIdx == 0) {
1669	            AscendC::Sum(
1670	                lossSumUb,
1671	                vecTmpUb,
1672	                sharedTmpBuffer,
1673	                {static_cast<uint32_t>(1), static_cast<uint32_t>(calcSizeAlign), static_cast<uint32_t>(calcSize)});
1674	            PipeBarrier<PIPE_V>();
1675	        } else {
1676	            AscendC::Sum(
1677	                tmpLossUb,
1678	                vecTmpUb,
1679	                sharedTmpBuffer,
1680	                {static_cast<uint32_t>(1), static_cast<uint32_t>(calcSizeAlign), static_cast<uint32_t>(calcSize)});
1681	            PipeBarrier<PIPE_V>();
1682	            // 与之前基本块的loss相加
1683	            AscendC::Add(lossSumUb, lossSumUb, tmpLossUb, 8);
1684	            PipeBarrier<PIPE_V>();
1685	        }
1686	    }
1687	
1688	    if (isLastBasicBlock && (runInfo.kLoopTimes > 1 || vRealKSize != 0)) {
1689	        event_t eventIdVToMTE3 = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE3>());
1690	        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(eventIdVToMTE3);
1691	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(eventIdVToMTE3);
1692	        AscendC::PipeBarrier<PIPE_MTE3>();
1693	        AscendC::SetAtomicAdd<float>();
1694	
1695	        if constexpr (deterministic) {
1696	            AscendC::DataCopyPad(lossResGm[constInfo.aivIdx],
1697	                                 lossSumUb,
1698	                                 {static_cast<uint32_t>(1),
1699	                                  static_cast<uint32_t>(4),
1700	                                  static_cast<uint32_t>(0),
1701	                                  static_cast<uint32_t>(0)});
1702	        } else {
1703	            AscendC::DataCopyPad(lossGm,
1704	                                 lossSumUb,
1705	                                 {static_cast<uint32_t>(1),
1706	                                  static_cast<uint32_t>(4),
1707	                                  static_cast<uint32_t>(0),
1708	                                  static_cast<uint32_t>(0)});
1709	        }
1710	        SetAtomicNone();
1711	        GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE3>(eventIdVToMTE3);
1712	    }
1713	}
1714	
