764	
765	template <typename SLIT> __aicore__ inline void SLITMatmulService<SLIT>::ComputeMm1(const SLIGradKLLossRunInfo &info)
766	{
767	    if (info.mergeKv) {
768	        ComputeMm1Sparse(info);
769	    } else {
770	        ComputeMm1Dense(info);
771	    }
772	}
773	
774	template <typename SLIT> __aicore__ inline void SLITMatmulService<SLIT>::ComputeMm2(const SLIGradKLLossRunInfo &info)
775	{
776	    uint32_t dSize = constInfo.dSizeQueryIndex;
777	    uint32_t kTailLoopSize = N_WORKSPACE_SIZE;
778	    uint32_t kInnerLoopTimes = N_WORKSPACE_SIZE / N_SPLIT_SIZE;
779	    uint32_t tailLoopKSize = N_SPLIT_SIZE;
780	
781	    mmParam.singleM = constInfo.gSizeQueryIndex;
782	    mmParam.singleN = N_SPLIT_SIZE;
783	    mmParam.singleK = constInfo.dSizeQueryIndex;
784	    mmParam.isLeftTranspose = false;
785	    mmParam.isRightTranspose = false;
786	    mmParam.isOutKFisrt = true;
787	    mmParam.isFixOut = true;
788	    mmParam.isL0CAccum = false;
789	
790	    for (uint32_t kOuterIdx = 0; kOuterIdx < info.s2LoopTimes; kOuterIdx++) {
791	        if (kOuterIdx == 0) {
792	            // 搬运query到L1 64 * 128 * sizeof(fp16)
793	            WaitFlag<AscendC::HardEvent::MTE1_MTE2>(QUERY_INDEX_EVENT[indexPingPongFlag & 1]);
794	            CopyInMm2AToL1(l1QIndexTensor[indexPingPongFlag & 1], info, constInfo.gSizeQueryIndex, dSize, 0);
795	        }
796	
797	        if (kOuterIdx == info.s2LoopTimes - 1) {
798	            kTailLoopSize = info.kRealSize - kOuterIdx * N_WORKSPACE_SIZE;
799	            kInnerLoopTimes = AlignTo(kTailLoopSize, N_SPLIT_SIZE) / N_SPLIT_SIZE;
800	            tailLoopKSize = kTailLoopSize - (kInnerLoopTimes - 1) * N_SPLIT_SIZE;
801	        }
802	
803	        CrossCoreWaitFlag<SYNC_MODE, PIPE_MTE2>(SYNC_V0_TO_C1_SY_FLAG[kOuterIdx & 1]);
804	        // 此处同步id需要与v0对齐
805	        for (uint32_t kInnerIdx = 0; kInnerIdx < kInnerLoopTimes; kInnerIdx++) {
806	            if (kInnerIdx == kInnerLoopTimes - 1) {
807	                mmParam.singleN = tailLoopKSize;
808	            }
809	            int64_t gatherWorkspaceOffset;
810	            if (info.mergeKv) {
811	                gatherWorkspaceOffset = info.taskIdMod2 * constInfo.kSize * dSize +
812	                                        kOuterIdx * N_WORKSPACE_SIZE * dSize + kInnerIdx * N_SPLIT_SIZE * dSize;
813	            } else {
814	                gatherWorkspaceOffset =
815	                    info.keyIndexTensorOffset + kOuterIdx * N_WORKSPACE_SIZE * dSize + kInnerIdx * N_SPLIT_SIZE * dSize;
816	            }
817	            int64_t outWorkspaceOffset = kOuterIdx * N_WORKSPACE_SIZE + kInnerIdx * N_SPLIT_SIZE;
818	            // 搬运gather到L1 128 * 128 * sizeof(fp16)
819	            LocalTensor<MM_OUT_T> l0cTensor = cL0TensorPingPong[l0cPingPongFlag & 1];
820	            LocalTensor<KV_T> kTensor = l1KVTensor[gatherPingPongFlag & 1];
821	            // 反向同步mte1_mte2
822	            WaitFlag<AscendC::HardEvent::MTE1_MTE2>(SYNC_MTE21_FLAG[gatherPingPongFlag & 1]);
823	            CopyInMm2BToL1(kTensor, info, gatherWorkspaceOffset, mmParam.singleN, dSize, dSize);
824	            SetFlag<AscendC::HardEvent::MTE2_MTE1>(SYNC_MTE21_FLAG[gatherPingPongFlag & 1]);
825	            WaitFlag<AscendC::HardEvent::MTE2_MTE1>(SYNC_MTE21_FLAG[gatherPingPongFlag & 1]);
826	            GlobalTensor<MM_OUT_T> resGm = mm2ResGm[info.taskIdMod2][outWorkspaceOffset];
827	            MmadInner(l0cTensor, l1QIndexTensor[indexPingPongFlag & 1], kTensor, mmParam);
828	            SetFlag<AscendC::HardEvent::MTE1_MTE2>(SYNC_MTE21_FLAG[gatherPingPongFlag & 1]);
829	            if (mmParam.isFixOut) {
830	                SetFlag<AscendC::HardEvent::M_FIX>(SYNC_MMFIX_FLAG[l0cPingPongFlag & 1]);
831	                WaitFlag<AscendC::HardEvent::M_FIX>(SYNC_MMFIX_FLAG[l0cPingPongFlag & 1]);
832	                FixpipeParamsV220 fixpipeParams;
833	                fixpipeParams.nSize = mmParam.singleN;
834	                fixpipeParams.mSize = mmParam.singleM;
835	                fixpipeParams.srcStride = ((fixpipeParams.mSize + 15) / 16) * 16;
836	                fixpipeParams.dstStride = constInfo.kSize;
837	                fixpipeParams.ndNum = 1;
838	                fixpipeParams.srcNdStride = 0;
839	                fixpipeParams.dstNdStride = 0;
840	                fixpipeParams.reluEn = true;
841	                Fixpipe<MM_OUT_T, MM_OUT_T>(resGm, l0cTensor, fixpipeParams); // 将matmul结果从L0C搬运到UB
842	            }
843	            SetFlag<AscendC::HardEvent::FIX_M>(SYNC_MMFIX_FLAG[l0cPingPongFlag & 1]);
844	            l0cPingPongFlag = (l0cPingPongFlag + 1) & 1;
845	            gatherPingPongFlag = (gatherPingPongFlag + 1) & 1;
846	        }
847	    }
848	    // 此处同步id需要与v1对齐
849	    CrossCoreSetFlag<SYNC_MODE, PIPE_FIX>(SYNC_C1_TO_V1_SY_FLAG[info.taskIdMod2]);
850	    mm2ResPingPongFlag = (mm2ResPingPongFlag + 1) & 1;
851	}
852	
853	template <typename SLIT> __aicore__ inline void SLITMatmulService<SLIT>::ComputeMm5(const SLIGradKLLossRunInfo &info)
854	{
855	    uint32_t kLoopSize = RELU_GRAD_SPLIT_SIZE;
856	    uint32_t kInnerLoopTimes = RELU_GRAD_SPLIT_SIZE / K_SPLIT_SIZE;
857	    uint32_t tailLoopKSize = K_SPLIT_SIZE;
858	
859	    mmParam.singleM = K_SPLIT_SIZE;
860	    mmParam.singleN = constInfo.dSizeQueryIndex;
861	    mmParam.singleK = constInfo.gSizeQueryIndex;
862	    mmParam.isLeftTranspose = true;
863	    mmParam.isRightTranspose = true;
864	    mmParam.isOutKFisrt = true;
865	    mmParam.isFixOut = true;
866	    mmParam.isL0CAccum = false;
867	
868	    CrossCoreWaitFlag<SYNC_MODE, PIPE_MTE2>(SYNC_V1_TO_C2_DW_FLAG[info.taskIdMod2]);
869	    int64_t scatterOffset = 0;
870	    int64_t resOffset = constInfo.aicIdx * constInfo.kSize * constInfo.dSizeQueryIndex * 2;
871	    GlobalTensor<MM_OUT_T> resGm;
872	    if constexpr (deterministic) {
873	        resGm = mm5ResGm[resOffset + info.taskIdMod2 * constInfo.kSize * constInfo.dSizeQueryIndex];
874	        mmParam.isAtomicAdd = false;
875	    } else {
876	        if (info.mergeKv) {
877	            resGm = mm5ResGm[resOffset + info.taskIdMod2 * constInfo.kSize * constInfo.dSizeQueryIndex];
878	            mmParam.isAtomicAdd = false;
879	        } else {
880	            resGm = scatterAddResGm[info.keyIndexTensorOffset];
881	            mmParam.isAtomicAdd = true;
882	        }
883	    }
884	
885	    int64_t kOuterStride = info.kBaseSize * constInfo.dSizeQueryIndex;
886	    int64_t kInnerStride = K_SPLIT_SIZE * constInfo.dSizeQueryIndex;
887	    for (uint32_t kOuterIdx = 0; kOuterIdx < info.kLoopTimes; kOuterIdx++) {
888	        if (kOuterIdx == info.kLoopTimes - 1) {
889	            kLoopSize = info.kRealSize - kOuterIdx * RELU_GRAD_SPLIT_SIZE;
890	            kInnerLoopTimes = AlignTo(kLoopSize, K_SPLIT_SIZE) / K_SPLIT_SIZE;
891	            tailLoopKSize = kLoopSize - (kInnerLoopTimes - 1) * K_SPLIT_SIZE;
892	        }
893	        if (IS_RELUGRAD_REUSE) {
894	            WaitFlag<AscendC::HardEvent::MTE1_MTE2>(RELU_GRAD_EVENT);
895	        }
896	        int64_t reLuGradWorkspaceOffset = kOuterIdx * RELU_GRAD_SPLIT_SIZE;
897	        WaitFlag<AscendC::HardEvent::MTE1_MTE2>(SYNC_MM_RELU_GRAD_EVENT);
898	        CopyInMm5AToL1(l1ReLuGradTensor, info, constInfo.gSizeQueryIndex, kLoopSize, reLuGradWorkspaceOffset);
899	        SetFlag<AscendC::HardEvent::MTE2_MTE1>(SYNC_MTE21_FLAG[indexPingPongFlag & 1]);
900	        WaitFlag<AscendC::HardEvent::MTE2_MTE1>(SYNC_MTE21_FLAG[indexPingPongFlag & 1]);
901	        for (uint32_t kInnerIdx = 0; kInnerIdx < kInnerLoopTimes; kInnerIdx++) {
902	            int64_t reluGradOffset =
903	                kInnerIdx * M_SPLIT_SIZE * AlignTo(constInfo.gSizeQueryIndex, static_cast<uint32_t>(C0_SIZE));
904	            // 搬运 result 128 * 128 * fp16
905	            LocalTensor<MM_OUT_T> l0cTensor = cL0TensorPingPong[l0cPingPongFlag & 1];
906	            GlobalTensor<MM_OUT_T> resTmpGm = resGm[kOuterIdx * kOuterStride + kInnerIdx * kInnerStride];
907	            LocalTensor<Q_T> reLuTensor = l1ReLuGradTensor[reluGradOffset];
908	            if (kInnerIdx == kInnerLoopTimes - 1) {
909	                mmParam.singleM = tailLoopKSize;
910	            }
911	            MmadInner(l0cTensor, reLuTensor, l1QIndexTensor[indexPingPongFlag & 1], mmParam);
912	            ScatterAdd(resTmpGm, l0cTensor, mmParam, info, scatterOffset);
913	            l0cPingPongFlag = (l0cPingPongFlag + 1) & 1;
914	        }
915	        SetFlag<AscendC::HardEvent::MTE1_MTE2>(SYNC_MM_RELU_GRAD_EVENT);
916	        mm5ResPingPongFlag = 1 - mm5ResPingPongFlag;
917	    }
918	    SetFlag<AscendC::HardEvent::MTE1_MTE2>(QUERY_INDEX_EVENT[indexPingPongFlag & 1]);
