27	using AscendC::CrossCoreSetFlag;
28	using AscendC::CrossCoreWaitFlag;
29	
30	template <typename SLIT> class SLIKLLossVector2Service {
31	  public:
32	    // 中间计算数据类型为float，高精度模式
33	    using T = float;
34	    using Q_T = typename SLIT::inputQT;
35	    using KV_T = typename SLIT::inputKT;
36	    using OUT_T = typename SLIT::outputT;
37	    using Q_ROPE_T = Q_T;
38	    using K_ROPE_T = KV_T;
39	    using MM12_OUT_T = T;
40	    using MM3_OUT_T = T;
41	
42	    static constexpr SLILayout LAYOUT_T = SLIT::inputQLayout;
43	    static constexpr SLILayout KV_LAYOUT_T = SLIT::inputKLayout;
44	    static constexpr bool deterministic = SLIT::deterministic;
