160	template <typename SLIT> __aicore__ inline void SLIKLLossVector2Service<SLIT>::ProcessVector2()
161	{
162	    // 输入数据[T2,Nidx2,D]
163	    // T2切多核，执行前需要做全核同步
164	
165	    int64_t totalCost = 0;
166	    if constexpr (KV_LAYOUT_T == SLILayout::TND) {
167	        totalCost = actualSeqLengthsKVGm.GetValue(constInfo.bSize - 1);
168	    } else {
169	        totalCost = constInfo.bSize * constInfo.s2Size;
170	    }
171	
172	    int64_t totalCoreNum = GetBlockNum() * GetTaskRation();
173	    int64_t avgCost = CeilDiv(totalCost, totalCoreNum);
174	
175	    int32_t t2Start = Min(constInfo.aivIdx * avgCost, totalCost);
176	    int32_t t2End = Min(t2Start + avgCost, totalCost);
177	
178	    int32_t t2ProcessSize = UB_ROW_SIZE;
179	    int32_t t2TailSize = ((t2End - t2Start) % UB_ROW_SIZE == 0) ? UB_ROW_SIZE : ((t2End - t2Start) % UB_ROW_SIZE);
180	    int32_t pingPongIdx = 0;
181	
182	    LocalTensor<MM3_OUT_T> copyInUb;
183	    LocalTensor<OUT_T> copyOutUb;
184	
185	    for (int32_t t2Idx = t2Start; t2Idx < t2End; t2Idx += UB_ROW_SIZE) {
186	        if (t2Idx + UB_ROW_SIZE >= t2End) {
187	            t2ProcessSize = t2TailSize;
188	        }
189	
190	        WaitFlag<AscendC::HardEvent::V_MTE2>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
191	        copyInUb = mm3ResUb[pingPongIdx * (UB_ROW_SIZE * constInfo.dSizeQueryIndex)];
192	        DataCopy(
193	            copyInUb, scatterAddResGm[t2Idx * constInfo.dSizeQueryIndex], t2ProcessSize * constInfo.dSizeQueryIndex);
194	
195	        SetFlag<AscendC::HardEvent::MTE2_V>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
196	        WaitFlag<AscendC::HardEvent::MTE2_V>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
197	
198	        WaitFlag<AscendC::HardEvent::MTE3_V>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
199	        copyOutUb = castOutUb[pingPongIdx * (UB_ROW_SIZE * constInfo.dSizeQueryIndex)];
200	        Cast(copyOutUb, copyInUb, RoundMode::CAST_ROUND, t2ProcessSize * constInfo.dSizeQueryIndex);
201	        SetFlag<AscendC::HardEvent::V_MTE2>(SYNC_SCATTER_BUF_FLAG + pingPongIdx); // 释放copyInUb
202	
203	        SetFlag<AscendC::HardEvent::V_MTE3>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
204	        WaitFlag<AscendC::HardEvent::V_MTE3>(SYNC_SCATTER_BUF_FLAG + pingPongIdx);
205	
206	        DataCopy(dKeyIndexGm[t2Idx * constInfo.dSizeQueryIndex], copyOutUb, t2ProcessSize * constInfo.dSizeQueryIndex);
207	        SetFlag<AscendC::HardEvent::MTE3_V>(SYNC_SCATTER_BUF_FLAG + pingPongIdx); // 释放copyOutUb
208	
209	        pingPongIdx = 1 - pingPongIdx;
210	    }
211	    if (deterministic && constInfo.aivIdx == 0) {
212	        DataCopyExtParams inputLossCopyParams = {1, static_cast<uint32_t>(totalCoreNum * sizeof(T)), 0, 0, 0};
213	        DataCopyPadExtParams<T> copyPadParams = {false, 0, 0, 0};
214	        AscendC::DataCopyPad(inputLossUb, lossResGm, inputLossCopyParams, copyPadParams);
215	        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(MTE2ToVFlag);
216	        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(MTE2ToVFlag);
217	        AscendC::Sum(lossUb,
218	                     inputLossUb,
219	                     tmpUb,
220	                     {1,
221	                      static_cast<uint32_t>((totalCoreNum * sizeof(T) + 32 - 1) / 32 * 32 / sizeof(T)),
222	                      static_cast<uint32_t>(totalCoreNum)});
223	        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(VToMTE3Flag);
224	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(VToMTE3Flag);
225	        DataCopyExtParams lossCopyParams = {1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
226	        AscendC::DataCopyPad(lossGm, lossUb, lossCopyParams);
227	    }
