#ifndef SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_VECTOR2_H
#define SPARSE_LIGHTNING_INDEXER_GRAD_KL_LOSS_ENHANCE_VECTOR2_H

#include "kernel_operator.h"
#include "kernel_operator_list_tensor_intf.h"
#include "kernel_tiling/kernel_tiling.h"
