712	__aicore__ inline void SLIKLLossVectorService<SLIT>::ProcessVector1(SLIGradKLLossRunInfo &runInfo)
713	{
714	    eventIdMte2ToV4SY = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_V>());
715	    eventIdVToMte24SY = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::V_MTE2>());
716	
717	    CrossCoreWaitFlag(SYNC_C1_TO_V1_P_FLAG[runInfo.taskIdMod2]);
718	    CrossCoreWaitFlag(SYNC_C1_TO_V1_SY_FLAG[runInfo.taskIdMod2]);
719	    PreloadWeight(runInfo);
720	    AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(eventIdMTE3ToVTmp);
721	    // 保证 reduceN 轴的S'Y在同一个Vec核内 将P和S'Y任务分割
722	    if (runInfo.calcP) {
723	        VectorP(runInfo);
724	    } else {
725	        VectorSy(runInfo); // 计算S'Y部分，一直到Softmax
726	    }
727	    AscendC::CrossCoreSetFlag<0x1, PIPE_MTE3>(0x8);
728	    AscendC::CrossCoreWaitFlag<0x1, PIPE_MTE2>(0x8);
729	    for (int32_t kLoopIdx = 0; kLoopIdx < runInfo.kLoopTimes; ++kLoopIdx) {
730	        VectorDwDqDk(runInfo, kLoopIdx); // Sub + Mul + Mul + ReluGrad
731	        if (kLoopIdx >= runInfo.kLoopTimes - 1) {
732	            CrossCoreSetFlag<2, PIPE_MTE3>(SYNC_V1_TO_C2_DW_FLAG[runInfo.taskIdMod2]);
733	        }
734	        VectorLoss(runInfo, kLoopIdx);
735	    }
736	    AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(eventIdMTE3ToVTmp);
737	
738	    GetTPipePtr()->ReleaseEventID<HardEvent::MTE2_V>(eventIdMte2ToV4SY);
739	    GetTPipePtr()->ReleaseEventID<HardEvent::V_MTE2>(eventIdVToMte24SY);
740	}
